import AppKit

/// The recorder panel from the recording's END to the note that says where
/// it went (road map 3, R1c) — `RecorderPanelController.swift`'s fourth
/// file, cut out of `+Recording.swift` along the line `recordingEnded`
/// draws when the R1 review's fixes took that file past the 400-line cap:
/// everything before the session's `onFinish` fires stays there, everything
/// after it is here.
///
/// **One door for a finished recording.** The session's `onFinish` — called
/// exactly once whoever ended the recording: the panel's Stop, the status
/// item's, the system indicator's, a display that slept, a failure — arrives
/// at `recordingEnded`, which tears the recording chrome down (the tick, the
/// status item, and the `hiddenForRecording` flag that made `show()` beep —
/// clearing it, and showing NOTHING) and then lands. A DOCUMENT target
/// commits the placement through the document's
/// own door (`performGroupedEdit`, then `generateCaches`, the selection, and
/// the editor told through `viewStateDidChange`); a NEW PROJECT is
/// `ProjectDocument.untitled(around:)`, which does everything. A document
/// mid-drag is not committed over the gesture's base handle: the landing is
/// retried from a half-second timer until the drag ends, bounded at forty
/// tries — **20 s, kept** (lane C's flag, closed by reading): a landing that
/// waited for ever would hold the file's note back for ever, and the note
/// after the bound names the file, which is on disk either way — and on
/// either failure the note names the FILE, which is on disk whatever went
/// wrong after it. That timer stays in the DEFAULT run-loop mode on
/// purpose, unlike the countdown and the tick: a drag runs the loop in
/// tracking mode, so the retry fires when the drag ENDS, which is the
/// moment it is for.
///
/// **The commit is checked by its handle** (R1 review). `performGroupedEdit`
/// answers nothing: a refusal beeps or puts up the core's sentence on the
/// document's window and returns, and the panel — which cannot see either
/// — used to report "added" over a project with nothing in it. The
/// document's `project` handle changes ONLY on success (`applyEdit`'s three
/// outcomes), so `land` reads it before the commit and compares after, and
/// an unchanged handle is a failed landing with the file's path in the
/// note. The trial in `RecordingLanding.placement` sees everything the
/// commit will, so the arm is reached only by a race the trial cannot see —
/// an edit landing between the two on the same run-loop turn — and it is
/// there because the alternative is a note that lies.
///
/// **The note says six things, in order**, through `landingNote`, a pure
/// function so a probe can pin every combination without a landing: how the
/// recording ended when it was not this panel's own Stop (`.stopped` is the
/// status item's Stop too; `.userStopped` is the SYSTEM's indicator, and the
/// sentence names it so, now that Frame Job's own item is a menu-bar item as
/// well); that the document the person CHOSE had closed, when the choice
/// was a document and the landing opened a new project (R1 review — the
/// fallback is exact, and a person who chose "Untitled 2" should not have
/// to work out why a new window appeared instead); the segments left out
/// because their movie would not probe (`unreadableNote`, #97), each naming
/// the files it kept; the microphone's
/// problem, when the recording is a `.success` whose `micProblem` is set —
/// a success, not an error, so the picture lands first and the sentence
/// follows it; a resume the recorder refused (`resumeProblem`, STATE on the
/// panel and never text read back off the label — the R2 review's defect:
/// each end replaced the label whole, so after a refused resume and a clean
/// Stop the note was empty and the reveal showed nothing, the opposite of
/// what `+Pause.swift` promised); and the placement's own notes, one per
/// file the landing could not place. `failedToLand` names every file
/// through `filesClause` and carries the unreadable segments', the
/// microphone's and the resume's sentences too.
///
/// **The panel comes back ONLY with something to say** (decision 7, R2c).
/// It ordered out at `recordingDidStart` whatever the source, and each of
/// the three ends — `landed`, `failedToLand`, the failure arm of
/// `recordingEnded` — finishes with `revealIfNoted()`, AFTER its note is
/// set: the panel is ordered front when it was on screen as the recording
/// began (`showWhenLanded`) and the note is non-empty, and `showWhenLanded`
/// is cleared either way. A clean recording lands in its document or opens
/// its project and the panel stays away; ⌥⌘N shows it again. The reveal
/// belongs to the END and not to `recordingEnded`, because the deferred
/// landing's retries can put twenty seconds between the two, and a panel
/// shown with "Adding…" and no note yet is the dialog the user asked to be
/// rid of.
extension RecorderPanelController {
    static let landingRetryInterval: TimeInterval = 0.5
    static let landingRetryLimit = 40
    static let destinationClosedSentence =
        "The document you chose was closed, so the recording opened as a new project."

    // MARK: - The end, and the landing

    func recordingEnded(_ outcome: Result<RecordingResult, Error>) {
        disarmTick()
        statusItem?.remove()
        statusItem = nil
        launched = false
        hiddenForRecording = false
        switch outcome {
        case .failure(let error):
            phase = .idle
            setNote(
                [error.localizedDescription, resumeProblem].compactMap { $0 }
                    .joined(separator: " "))
            revealIfNoted()
        case .success(let result):
            phase = .landing
            landingAttempts = 0
            land(result)
        }
    }

    func land(_ result: RecordingResult) {
        switch RecordingLanding.resolve(result.choice.destination) {
        case .document(let document):
            guard !document.isLiveEditing else {
                deferLanding(result)
                return
            }
            do {
                let placement = try RecordingLanding.placement(result, in: document, place: true)
                let before = document.project
                document.performGroupedEdit(RecordingLanding.actionName, placement.ops)
                // The handle changes only on success (the type doc).
                guard document.project !== before else {
                    failedToLand(
                        result,
                        ReelCoreError(
                            message: "the project refused the placement and nothing was added"))
                    return
                }
                document.generateCaches()
                // Every segment's clip, microphone clips included (R2b); a
                // segment that minted none is a nil entry, and its sentence
                // is in `placement.notes`.
                document.selection = Set(
                    (placement.clipIds + placement.micClipIds + placement.leftOutMicClipIds
                        + placement.cameraClipIds)
                        .compactMap { $0 })
                Self.editor(of: document)?.viewStateDidChange()
                landed(result, asNewProject: false, notes: placement.notes)
                RecordingCutout.apply(result, in: document)  // CO-81: its own step, first
                RecordingEnhance.follow(result, in: document)  // AU-68: after the commit
                RecordingPolish.follow(result, in: document)  // CU-100: after it, its own steps
            } catch {
                failedToLand(result, error)
            }
        case .newProject:
            do {
                let (opened, notes) = try ProjectDocument.untitled(around: result)
                landed(result, asNewProject: true, notes: notes)
                RecordingCutout.apply(result, in: opened)  // CO-81: its own step, first
                RecordingEnhance.follow(result, in: opened)  // AU-68: after the commit
                RecordingPolish.follow(result, in: opened)  // CU-100: after it, its own steps
            } catch {
                failedToLand(result, error)
            }
        }
    }

    /// A drag is in progress: try again when it has had half a second to
    /// end, up to the limit — a landing over the gesture's base handle would
    /// be undone by the gesture's own end.
    private func deferLanding(_ result: RecordingResult) {
        landingAttempts += 1
        guard landingAttempts <= Self.landingRetryLimit else {
            let waited = Int(Double(Self.landingRetryLimit) * Self.landingRetryInterval)
            failedToLand(
                result,
                ReelCoreError(message: "A drag was still in progress after \(waited) s."))
            return
        }
        landingTimer?.invalidate()
        landingTimer = Timer.scheduledTimer(
            withTimeInterval: Self.landingRetryInterval, repeats: false
        ) { [weak self] _ in
            self?.landingTimer = nil
            self?.land(result)
        }
    }

    /// Back to idle; the note is `landingNote`'s, over the placement's own
    /// notes — the unreadable segments' sentences followed by what became of
    /// their readable voices (#181 item 2), said only here, on a landing
    /// that succeeded — led by every segment's camera sentences beside the
    /// screen (`cameraSegmentsNote`, spec §11 CAM-10 (8)) — and the reveal
    /// last.
    private func landed(_ result: RecordingResult, asNewProject: Bool, notes placed: [String]) {
        phase = .idle
        rebuildDestinations()
        // Then every segment's cursor problem (spec §11 CU-18).
        let notes = [result.cameraSegmentsNote, result.cursorSegmentsNote].compactMap { $0 } + placed
        let leftOut = [result.unreadableNote, result.leftOutVoiceNote].compactMap { $0 }
        setNote(
            Self.landingNote(
                stoppedBy: result.stoppedBy, chosen: result.choice.destination,
                landedAsNewProject: asNewProject, micProblem: result.micProblem,
                resumeProblem: resumeProblem, notes: notes,
                unreadable: leftOut.isEmpty ? nil : leftOut.joined(separator: " "),
                camera: result.camera, cameraBeside: result.camera != nil && !result.isCamera))
        revealIfNoted()
    }

    /// The files are on disk whatever went wrong after them, so the note
    /// names every one (`filesClause`: each segment's movie, and the
    /// microphone files that landed) — then what became of an unreadable
    /// segment, the microphone, the camera (its `problem` and warm-up `note`,
    /// spec §11 CAM-5, then each segment's camera sentences beside the
    /// screen, CAM-10 (8)) and a refused resume, when the result or the panel
    /// carries those sentences — and the reveal last.
    private func failedToLand(_ result: RecordingResult, _ error: any Error) {
        phase = .idle
        var note =
            "The recording was saved at \(result.filesClause) but could not be added: "
            + error.localizedDescription
        for sentence in [
            result.unreadableNote, result.micProblem, result.camera?.problem, result.camera?.note,
            result.cameraSegmentsNote, result.cursorSegmentsNote, resumeProblem,
        ].compactMap({ $0 })
        {
            note += " " + sentence
        }
        setNote(note)
        revealIfNoted()
    }

    /// The panel back on screen after a landing, ONLY when it was on screen
    /// as the recording began and the note has something in it (the type
    /// doc). Called LAST by each of the three ends, after the note is set —
    /// which is the whole point — and reached after the deferred landing's
    /// retries as well, since nothing before it clears `showWhenLanded`.
    /// Cleared either way, so a later `show()` of the person's own is not
    /// mistaken for this one. Internal so a probe can drive both ways.
    func revealIfNoted() {
        if showWhenLanded, !noteLabel.stringValue.isEmpty { window?.orderFront(nil) }
        showWhenLanded = false
    }

    /// The landing's note (the type doc): the stop's sentence unless the
    /// stop was this panel's own; the closed-document sentence when a chosen
    /// document was gone by the time the recording ended; the unreadable
    /// segments' sentences; the microphone's problem; a refused resume's
    /// sentence; then the placement's notes. Empty for the ordinary case, so
    /// `setNote` hides the label. The R2 arguments, #97's `unreadable` and
    /// CR1c's `camera` are LAST and default, so the probe's R1 rows read as
    /// they did. A CAMERA result (spec §11 CAM-5) says its own stop — the
    /// camera's `problem`, else that it stopped on its own — in place of the
    /// display's, and its warm-up `note` follows the microphone's problem.
    /// A camera BESIDE the screen (`cameraBeside`, spec §11 CAM-10 (8)) is
    /// not the recording's stop: the display's sentence stays, and the
    /// camera's `problem` follows the microphone's problem, before its note.
    static func landingNote(
        stoppedBy: StopReason, chosen: RecordingDestination, landedAsNewProject: Bool,
        micProblem: String?, resumeProblem: String? = nil, notes: [String] = [],
        unreadable: String? = nil, camera: RecordingCamera? = nil, cameraBeside: Bool = false
    ) -> String {
        var sentences: [String] = []
        switch stoppedBy {
        case .stopped:
            break
        case .userStopped:
            sentences.append(
                "Stopped from the system's screen-recording indicator; the recording was added.")
        case .systemStopped:
            if let camera, !cameraBeside {
                sentences.append(
                    (camera.problem ?? "The camera stopped on its own.")
                        + " What was captured was added.")
            } else {
                sentences.append(
                    "The system stopped the recording (the display slept or went away); "
                        + "what was captured was added.")
            }
        }
        if case .document = chosen, landedAsNewProject {
            sentences.append(destinationClosedSentence)
        }
        if let unreadable { sentences.append(unreadable) }
        if let micProblem { sentences.append(micProblem) }
        if cameraBeside, let problem = camera?.problem { sentences.append(problem) }
        if let note = camera?.note { sentences.append(note) }
        if let resumeProblem { sentences.append(resumeProblem) }
        sentences.append(contentsOf: notes)
        return sentences.joined(separator: " ")
    }

    /// `AgentServer.editor(_:)`'s lookup; nil for a windowless document.
    static func editor(of document: ProjectDocument) -> EditorViewController? {
        document.windowControllers
            .compactMap { $0.contentViewController as? EditorViewController }
            .first
    }
}
// app/Sources/ProjectDocument+Recording.swift — a recording as a new
// document (road map 3, phase R1b, the `.newProject` landing; a sequence of
// segments since R2b).
//
// An `extension ProjectDocument` in its own file, `+DisplayStem`'s shape: the
// base file is far over the ~600-line cap and takes no code it does not have
// to. What it HAD to take is `adoptImported(_:source:fps:)` — `project` and
// `importSourceURL` are `private(set)` and `clampViewState()` is private, so
// an extension in another file cannot build the untitled document itself —
// and that method is `readMediaFile`'s post-probe body moved whole, so a
// recording becomes a document by the ONE spelling File ▸ Open uses for a
// movie (road map 3, decision 1: a recording is ordinary media).

import AppKit

extension ProjectDocument {
    /// The untitled, dirty document a finished recording opens as — spec
    /// §1's opening flow for a movie, with two differences the recorder
    /// asks for. The CANVAS takes the recorder's rate (`choice.rate`, 30 or
    /// 60 — the grid the person chose) while the media record keeps the
    /// file's own, which for a ScreenCaptureKit file is whatever the screen
    /// did (R0 measured 25.58 fps at a 1/60 interval; decision 3). And the
    /// REMAINDER — a paused recording's later segments, back to back on the
    /// first one's track, and every microphone file on a new back track —
    /// lands through `RecordingLanding.remainderPlacement` as ONE grouped
    /// edit; the FIRST segment is what the document IS.
    ///
    /// **The order is a contract**, measured on the real class by the
    /// document scout and once more by the review, and each step leans on
    /// the one before:
    ///
    /// 1. `openUntitledDocumentAndDisplay(false)` — the controller ADDS the
    ///    document itself (no `addDocument`, or it is listed twice) and,
    ///    with `false`, makes no window yet.
    /// 2. `adoptImported` — with the first segment's descriptor, and BEFORE
    ///    anything reads `displayName`: AppKit pins the name on its first
    ///    read, and the name is `defaultDraftName()`, which is the
    ///    recording's stem only once `importSourceURL` is set. Nothing
    ///    between 1 and 2 logs, summarises or shows the document.
    /// 3. **The import count** — `fileModificationDate = nil` and
    ///    `countEditChange(.changeDone)`, the two lines `makeWindowControllers`
    ///    runs for an opened movie (`ProjectDocument.swift`, under its
    ///    `importSourceURL != nil, fileURL == nil, !isDocumentEdited` guard)
    ///    — run HERE, before the remainder's edit and with or without one.
    ///    The position is the fix for a defect the review measured on the
    ///    change count: counted the other way round, the remainder's edit
    ///    dirtied the document first, `makeWindowControllers`' guard found
    ///    it edited and skipped its own count, and ONE ⌘Z brought the count
    ///    back to zero — a recording's document that read CLEAN, which ⌘W
    ///    then closed without asking. Counted first, the remainder's edit
    ///    stacks a SECOND count and its undo leaves the first standing, so
    ///    the document is dirty with the remainder or without it, as an
    ///    opened movie is. Without a remainder this is the same one count
    ///    `makeWindowControllers` would have made, one step earlier.
    /// 4. The remainder's grouped edit — named by
    ///    `RecordingLanding.remainderActionName(for:)`: "Add Microphone"
    ///    for one segment with any voice — its own or a left-out segment's
    ///    (#181 item 2) — "Add Camera and Microphone" or "Add Camera" for
    ///    one segment with a camera beside the screen, with a voice or
    ///    without (spec §11 CAM-10 (4)), "Add Recording Segments" otherwise,
    ///    and NOT "Add Recording", because the step removes the remainder
    ///    and keeps the first segment's picture, and the Edit menu should
    ///    say what ⌘Z will do — before the window, so the `generateCaches()`
    ///    inside `makeWindowControllers` covers EVERY file and the editor's
    ///    first composition is built once, over the finished project, rather
    ///    than rebuilt when the later clips land. Every op was trialled
    ///    purely by `remainderPlacement`, so the windowless commit cannot
    ///    reach `presentError`'s app-modal arm.
    /// 5. `makeWindowControllers()` — its own import count is guarded out by
    ///    step 3 (the guard counts only a document nothing has counted, which
    ///    is what makes the two orders equivalent for a movie and step 3
    ///    safe here); what it still does is run `generateCaches()` and
    ///    `ensureReversedMedia()` and add the editor window.
    /// 6. `showWindows()`.
    ///
    /// A throw after step 1 CLOSES the document it opened, or a failed
    /// landing would leave an invisible untitled draft in the controller
    /// with a blank project in it.
    ///
    /// **Answers the document AND the remainder's `notes`** — the sentences
    /// `remainderPlacement` wrote for each file it landed as media with no
    /// clip (a voice too short for a frame, a voice wholly under the previous
    /// one, or everything behind a first picture the core refused), each
    /// naming the file. A document cannot show a note, and a landing that
    /// swallowed them would leave a person looking for a voice that is in the
    /// Media tab and nowhere on the timeline; the panel's note and the tool's
    /// `note` field append them. Empty when everything landed, and always
    /// empty with no remainder. A tuple rather than a property on the
    /// document because the notes are about ONE landing, not about the
    /// document, and the two callers read them exactly once.
    ///
    /// Two limits, recorded. With one segment and no microphone the document
    /// has NO undo step — its first project is what the document is, as for
    /// an opened movie — while with a remainder, ⌘Z (Undo Add Microphone, or
    /// Undo Add Recording Segments) removes the remainder's media and clips
    /// and leaves the first picture, and the document STAYS dirty under it
    /// (step 3's count): the first segment is the document, the rest is an
    /// edit to it. And every file stays on disk on either undo, as undoing
    /// Add Media… leaves the file (road map 3 §0). Main thread.
    static func untitled(around result: RecordingResult) throws
        -> (document: ProjectDocument, notes: [String])
    {
        assert(Thread.isMainThread)
        let controller = NSDocumentController.shared
        guard let document = try controller.openUntitledDocumentAndDisplay(false)
            as? ProjectDocument
        else {
            throw ReelCoreError(
                message: "The untitled document did not open as a Frame Job project.")
        }
        var notes: [String] = []
        do {
            try document.adoptImported(
                result.descriptor, source: URL(fileURLWithPath: result.descriptor.path),
                fps: Fps(num: result.choice.rate, den: 1))
            // Step 3: the import count, BEFORE the remainder's edit — see the
            // doc comment for why the order is the fix.
            document.fileModificationDate = nil
            document.countEditChange(.changeDone)
            if let remainder = try RecordingLanding.remainderPlacement(result, in: document) {
                document.performGroupedEdit(
                    RecordingLanding.remainderActionName(for: result), remainder.ops)
                notes = remainder.notes
            }
        } catch {
            document.close()
            throw error
        }
        document.makeWindowControllers()
        document.showWindows()
        return (document, notes)
    }
}

// app/Sources/RecordingLanding.swift — where a finished recording goes
// (road map 3, phase R1b; a SEQUENCE of segments since R2b).
//
// A value type, `AudioNormalize`'s shape: a `RecordingResult` and a document
// in, an op list and the ids it will mint out, so the recorder panel and the
// `record_screen` tool provably land a recording the same way. **Nothing here
// commits.** The panel commits through `document.performGroupedEdit`, the
// tool through `AgentServer.performGroupedEdit`, and each door keeps its own
// posture on a refusal — a sheet, or an in-band error — which a document-side
// commit would collapse into the wrong one for the tool.
//
// A recording is a sequence of segments (road map 3, decision 6: a pause
// closes one file and a resume opens the next over the one stream), and the
// landing places them back to back — one clip per segment, each at the
// previous one's END as the core reports it — so a paused recording is `n`
// ordinary media files and `n` clips on ONE track, touching, and the model
// learns nothing. An unpaused recording is the one-segment case of the same
// list, byte for byte R1's.
//
// **Every clip is READ BACK after its apply**, never assumed (the R2
// review): the core snaps a start to the frame grid, and at an inexact
// canvas rate — decision 3's 24981/1000, a document opened from a
// recording — a clip's end is a sum of two grid points, which is NOT a grid
// point, so an `add_clip` at it can snap DOWN by up to half a frame into a
// one-tick overlap the rule accepts and a cross dissolve minted between two
// halves of one recording. `placeClip` reads the landed start and, when it is
// under the floor, places again a frame up; the rule is **touching, or a
// sub-frame gap at an inexact rate — never an overlap, never a transition**,
// and the gap is the documented limit of such a rate. A file the core would
// refuse outright — one whose length snaps to no frame at all — lands as
// MEDIA with a sentence in `Placement.notes`, rather than taking every other
// segment down with it.
//
// The ops come back UNSCOPED. Inside an open nest the caller's door stamps the
// scope (`ProjectDocument.addressed`, `AgentServer+Scope.addressed`): every
// `add_media` op is document-level and travels unscoped, everything else
// carries the nest, and that is exactly what the trial below applies — so the
// commit runs the list the trial ran.
//
// The microphone half — each segment's voice on ONE new back track, the
// floor rule that keeps two voices from overlapping, the names its track and
// its undo steps carry, and `untitled(around:)`'s remainder landing — is
// `RecordingLanding+Microphone.swift`, a pure move landed alone at the
// 400-line cap (road map 3, R2's toll) before it grew, and the placing of
// one clip on the grid — `placeBackToBack`, `placeClip`, `tooShortNote`,
// `mediaEntry`, `milliseconds` — is `RecordingLanding+Placing.swift`, the
// same toll paid again when the read-backs arrived. `addMedia`, `view`,
// `clip(_:in:scope:)` and `trimmed` are internal for them, because
// `private` does not cross a file. A VOICE-OVER's landing — every file on one
// new back Microphone track — is `RecordingLanding+VoiceOver.swift`. The same
// toll paid twice more at camera-recording CR3-0 moved `Placement` and
// `Landed` to `RecordingLanding+Placement.swift`, and `untitled(around:)`'s
// remainder and its undo steps' names to `RecordingLanding+Remainder.swift`.
// A camera beside the screen (spec §11 CAM-10) — its media, ONE front track
// named "Camera", each clip by its segment's offset and the recorder's layout — is
// `RecordingLanding+Camera.swift`, called between the pictures and the
// microphones. The ripples a Separate recording with Show Clicks lands its
// screen clips with (road map creator-jobs CU3c, spec §11 CU-31 (c)) are
// `RecordingLanding+Cursor.swift`'s `addRipples`, called right after the
// pictures.

import AppKit

struct RecordingLanding {
    enum Target {
        case document(ProjectDocument)
        case newProject
    }

    /// The undo step's name, for both doors — the whole landing, every
    /// picture and every microphone in one list.
    static let actionName = "Add Recording"

    // MARK: - Where

    /// The document a `.document(recipeKey:)` destination names, looked up
    /// among the open documents by `recipeKey` — minted by
    /// `RecipeSource.register()`, monotonic and never reused, so a document
    /// that closed mid-recording is a lookup that fails and not a dangling
    /// pointer or (the `ObjectIdentifier` trap `RelinkSheetController`
    /// records) the next document allocated at the same address. A miss, and
    /// `.newProject`, both answer `.newProject`. Main thread.
    static func resolve(_ destination: RecordingDestination) -> Target {
        assert(Thread.isMainThread)
        guard case .document(let key) = destination else { return .newProject }
        let open = NSDocumentController.shared.documents.compactMap { $0 as? ProjectDocument }
        guard let document = open.first(where: { $0.recipeKey == key }) else {
            return .newProject
        }
        return .document(document)
    }

    // MARK: - What

    /// PURE: the op list and the predicted ids for landing `result` in
    /// `document` at its playhead, in the container it has open — every
    /// segment, as ONE grouped edit.
    ///
    /// Each segment's picture media goes in first, in order, applied purely
    /// against the DOCUMENT's handle (`add_media` is document-level,
    /// `ReelOp.documentLevelNames`) and its id read off the result; then,
    /// with `place`, the pictures as a sequence on ONE track by the two-try
    /// track rule — all of them on the front track of the open container if
    /// the core accepts every one there, else all on a new track in front of
    /// everything (`addSequence`). The rule is `addGeneratedClip`'s
    /// (`EditorViewController+AddClips.swift`) but it cannot be that method:
    /// its probe runs against a project that does not hold the media yet,
    /// and `add_clip` naming an absent media is an `Err` — every recording
    /// would fall to the new-track branch, and the branch would then name
    /// the TRACK by the id `add_media` had consumed. `placeImageBackground`
    /// / `backgroundMedia(for:in:)` are the precedent: the probe runs over a
    /// project that already HOLDS the media.
    ///
    /// With microphone files the second half — each one's media, ONE new
    /// BACK track named "Microphone", each one's clip — is derived from the
    /// pictures' purely-applied result, never from one `next_id` read,
    /// because the pictures mint `n` or `n + 1` ids and which depends on the
    /// branch the track rule took. `place == false` lands every media (the
    /// microphones' included) with no clip at all.
    ///
    /// **A camera beside the screen** (spec §11 CAM-10) lands between the
    /// two: each segment's `(Camera).mov` as media, then — with `place` —
    /// ONE new FRONT track named "Camera" and each camera clip at its screen
    /// segment's start plus its `cameraOffset`, laid out (`addCameras`).
    /// The pictures → cameras → microphones order is the one grouped edit's.
    ///
    /// **A left-out segment's readable voice** (#181 item 2, spec §11
    /// recording) is a stretch of its own (`RecordingResult.stretches`): on
    /// the picture side a GAP of its slot's length (`pictureStretches`), so
    /// the pictures after it start at the slot's end, and on the microphone
    /// side a voice at offset 0 at the slot's start, by the same floor rule
    /// (`voices(of:)`); `split` reads the answers back per segment and per
    /// left-out segment. With no left-out voice the list is the segments.
    ///
    /// The playhead is nest-local while a nest is open, the ops are unscoped,
    /// and the trial stamps the document's scope on the container ops exactly
    /// as the commit will. Two refusals are thrown by name rather than
    /// answered with a list that would beep: a live gesture (the caller
    /// retries when it ends, rather than committing over the gesture's base
    /// handle) and anything the core refuses, with the core's own sentence.
    ///
    /// **The trial sees everything the commit will, the caps included.**
    /// Each scoped op is applied to the PARENT handle —
    /// `trial.applying(op.scoped(scope))` IS the scoped apply, not a view of
    /// it — so `check_caps` and `check_nesting`, which phase 9 runs once on
    /// the MERGED parent (`core/src/scope.rs`, `Project::finish`), refuse
    /// here with the core's own sentence exactly as they would at the
    /// commit: a document at `MAX_TRACKS` throws "too many tracks" before
    /// any list is answered, inside a nest or out of one
    /// (`tools/proof/recording_probe.py`, section 4, row 8).
    ///
    /// **One list, one limit.** The pictures and the microphones are ONE
    /// grouped edit, so a microphone pair the core refuses takes every
    /// picture down with it. The case that reaches it: a document at
    /// `MAX_TRACKS` with an empty front track takes the pictures alone (no
    /// track is added) and lands NOTHING once a microphone needs its own
    /// track. Kept on purpose — half a recording landed, with the voice
    /// missing and no undo step that says so, is worse than a refusal — and
    /// both doors name the FILES in the refusal, which are on disk whatever
    /// happened after them. What is NOT a refusal is a file the core cannot
    /// make a clip of at all: it lands as media, with a sentence in `notes`.
    static func placement(
        _ result: RecordingResult, in document: ProjectDocument, place: Bool
    ) throws -> Placement {
        assert(Thread.isMainThread)
        guard !document.isLiveEditing else {
            throw ReelCoreError(
                message: "A drag is in progress; the recording can be added when it ends.")
        }
        if result.isVoiceOver { return try voiceOverPlacement(result, in: document, place: place) }
        let scope = document.scope
        var trial = document.project
        var ops: [ReelOp] = []
        var notes: [String] = []

        var mediaIds: [UInt32] = []
        for segment in result.segments {
            mediaIds.append(try addMedia(segment.descriptor, to: &trial, ops: &ops))
        }
        var pictures: [Landed] = []
        if place {
            let stretches = try pictureStretches(
                of: result, mediaIds: mediaIds, in: trial, scope: scope)
            pictures = try addSequence(
                stretches, from: document.playhead, scope: scope, to: &trial, ops: &ops,
                notes: &notes)
            try addRipples(
                pictures.compactMap { $0.clip?.id }, of: result, scope: scope, to: &trial,
                ops: &ops)
        }
        let cameras = try addCameras(
            result, screenStarts: place ? segmentStarts(pictures.map { $0.at }, of: result) : nil,
            screenClips: split(pictures.map { $0.clip?.id }, of: result).segments,
            scope: scope, to: &trial, ops: &ops, notes: &notes)
        let microphones = try addMicrophones(
            voices(of: result), pictureStarts: place ? pictures.map { $0.at } : nil,
            scope: scope, to: &trial, ops: &ops, notes: &notes)
        let micMedia = split(microphones.media, of: result)
        let micClips = split(microphones.clips, of: result)
        return Placement(
            ops: ops, mediaIds: mediaIds,
            clipIds: place
                ? split(pictures.map { $0.clip?.id }, of: result).segments
                : mediaIds.map { _ in nil },
            micMediaIds: micMedia.segments, micClipIds: micClips.segments, notes: notes,
            leftOutMicMediaIds: micMedia.leftOut, leftOutMicClipIds: micClips.leftOut,
            cameraMediaIds: cameras.media, cameraClipIds: cameras.clips)
    }

    // MARK: - The steps, each applied purely and read back

    /// `add_media` applied purely; the id it minted, read off the result. A
    /// path already in the list is the documented IDENTITY
    /// (`core/src/edit_track.rs`), not a failure, and then the id is the
    /// entry's, matched by the TRIMMED path because that is what the core
    /// stored — `backgroundMedia(for:in:)`'s rule. The op stays in the list
    /// either way: `applying(_ ops:)` runs every later op after an identity,
    /// so one shape serves both cases and the undo step is one.
    static func addMedia(
        _ descriptor: MediaDescriptor, to trial: inout ReelProject, ops: inout [ReelOp]
    ) throws -> UInt32 {
        let op = ReelOp.addMedia(descriptor: descriptor)
        ops.append(op)
        if let added = try trial.applying(op).project {
            trial = added
            guard let id = added.snapshot.media.last?.id else {
                throw ReelCoreError(message: "\(descriptor.path) was added and is not listed.")
            }
            return id
        }
        let path = trimmed(descriptor.path)
        guard let id = trial.snapshot.media.first(where: { $0.path == path })?.id else {
            throw ReelCoreError(message: "\(path) could not be added to the media list.")
        }
        return id
    }

    /// The two-try track rule over a SEQUENCE, for a `trial` that holds
    /// every `media`: all of them back to back on the front track of the
    /// open container, from `at`; if any one REFUSES there — the overlap
    /// rule is the only reason the core has — ALL of them on a new track in
    /// front of everything, from the same `at`. The sequence never splits: a
    /// recording whose first segment sits on one track and whose second on
    /// another would read as two recordings, so a refusal part-way discards
    /// the front track's half-placed trial whole (it was a copy) and starts
    /// the new track's from the trial that holds the media and no clip. The
    /// new track's id is `next_id` off the trial, and each clip's is
    /// `next_id` off the trial before its own `add_clip`.
    ///
    /// Only a REFUSAL (nil) falls through to the new track. An `Err` from
    /// the first attempt propagates: the caps are the same on either track,
    /// so a `try?` here — R1's shape — turned "too many clips" on a full
    /// document into a second attempt that added a track and then reported
    /// "too many tracks", the wrong cap, when the document was at both.
    /// `notes` takes the winning attempt's sentences (the same either way —
    /// a picture too short for a frame is too short on any track). The
    /// sequence is the whole stretch list, a left-out voice's gap included,
    /// so the rule sees every picture where it will land.
    private static func addSequence(
        _ stretches: [PictureStretch], from at: Ticks, scope: UInt32?,
        to trial: inout ReelProject, ops: inout [ReelOp], notes: inout [String]
    ) throws -> [Landed] {
        let container = try view(of: trial, scope: scope).snapshot
        if let front = container.tracks.last?.id {
            var attempt = trial
            var attemptOps: [ReelOp] = []
            var attemptNotes: [String] = []
            if let placed = try placeBackToBack(
                stretches, on: front, from: at, scope: scope, to: &attempt, ops: &attemptOps,
                notes: &attemptNotes)
            {
                trial = attempt
                ops += attemptOps
                notes += attemptNotes
                return placed
            }
        }
        // Index 0 is the BACK of the stack (§6), so the count is the front.
        let addTrack = ReelOp.addTrack(index: container.tracks.count)
        let track = trial.snapshot.nextId
        guard let withTrack = try trial.applying(addTrack.scoped(scope)).project else {
            throw ReelCoreError(message: "A track for the recording could not be added.")
        }
        var attempt = withTrack
        var attemptOps: [ReelOp] = [addTrack]
        var attemptNotes: [String] = []
        guard
            let placed = try placeBackToBack(
                stretches, on: track, from: at, scope: scope, to: &attempt, ops: &attemptOps,
                notes: &attemptNotes)
        else {
            throw ReelCoreError(message: "The recording could not be placed on a new track.")
        }
        trial = attempt
        ops += attemptOps
        notes += attemptNotes
        return placed
    }

    /// The clip `id` as the core reports it, read off the CONTAINER the ops
    /// are measured against — the nest's view while a scope is open, since
    /// a nested clip is not in the parent's `clips`. An id the trial does
    /// not list after its own `add_clip` accepted it is a throw, not a
    /// guess.
    static func clip(_ id: UInt32, in trial: ReelProject, scope: UInt32?) throws -> ClipSnapshot {
        let container = try view(of: trial, scope: scope).snapshot
        guard let clip = container.clips.first(where: { $0.id == id }) else {
            throw ReelCoreError(message: "Clip \(id) was placed and is not listed.")
        }
        return clip
    }

    /// The container the clip ops are measured against: the nest's view
    /// while a scope is open (its tracks and clips at the top level, its
    /// `next_id` the parent's), else the trial itself. A scope naming a nest
    /// the trial has not got is a refusal, not a fallback — `clampViewState`
    /// clears one before anything reads it, so this arm is a race with an
    /// undo and the caller should not land on the timeline by accident.
    static func view(of trial: ReelProject, scope: UInt32?) throws -> ReelProject {
        guard let nest = scope else { return trial }
        guard let view = trial.scoped(nest) else {
            throw ReelCoreError(message: "The open nest (id \(nest)) is no longer in the project.")
        }
        return view
    }

    static func trimmed(_ path: String) -> String {
        path.trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

// app/Sources/RecordingLanding+Microphone.swift — the microphone half of
// the landing (road map 3, R1b; per segment since R2b), a PURE MOVE out of
// `RecordingLanding.swift` landed alone at the 400-line cap (R2's toll) and
// then grown here: the name the microphone's track carries,
// `addMicrophones` (every stretch's voice on ONE back track,
// by the floor rule — a left-out segment's readable voice, #181 item 2,
// among them, its stretches in `+LeftOut`) and `addMicrophoneClip`, the
// head-trim dance with every step of it READ BACK. `remainderPlacement`
// (everything a fresh untitled document does not already hold) and the two
// undo steps' names are `+Remainder`'s since camera-recording CR3-0.
// `addMedia`, `view`, `clip(_:in:scope:)` and `trimmed` are internal in
// the base file for this one, and `placeBackToBack`, `placeClip`,
// `mediaEntry`, `tooShortNote` and `milliseconds` in `+Placing`, because
// `private` does not cross a file. `headTrimmed` is internal for the same
// reason since camera-recording CR3b: `+Camera`'s clips take the same dance
// (spec §11 CAM-10 (2)).

import AppKit

extension RecordingLanding {
    /// The new back track every microphone clip lands on — ONE track for the
    /// whole recording, added once, before the first voice that takes a
    /// frame, so a paused recording's voices sit in a row under its pictures
    /// as its pictures do, and a recording none of whose voices can be
    /// placed adds no empty track.
    static let microphoneTrackName = "Microphone"

    /// Every stretch's microphone (`voices(of:)`, one per segment and per
    /// left-out voice): each file's `add_media` in order, then — when
    /// `pictureStarts` is given, one per voice — ONE new back track and each
    /// voice's clip by the floor rule, in the same order. A nil
    /// `pictureStarts` is `place: false`: the media land and no clip does,
    /// R1's rule; a nil ENTRY lands that voice as media only. Answers one
    /// media id and one clip id PER VOICE, nil where it has no file, or
    /// where it minted no clip — too short for a frame, or wholly under the
    /// previous voice, each with its sentence in `notes`.
    ///
    /// **The floor.** Segment `k`'s voice belongs at `pictureStart_k −
    /// micOffset_k`, and with one voice that is R1's rule exactly, floored at
    /// 0. With several, two voices on one track can neither overlap — a
    /// refusal, or worse a sub-frame overlap the rule ACCEPTS as a
    /// transition, minting a cross dissolve between two halves of one
    /// recording — nor be placed late (the same wrong sound as R1's negative
    /// start put at 0), so the floor for voice `k` is the previous voice's
    /// END, and a start below it is head-trimmed to it by the same dance.
    /// The floor is READ off the trial, never computed: the previous clip's
    /// end is on the frame grid because the core snapped its start and its
    /// length, and a sum over descriptor durations would not be. (At an
    /// inexact rate even that end is not a grid point, and `placeClip` steps
    /// the add up a frame when the core snaps under it.)
    ///
    /// The track is added on the attempt of the FIRST voice that takes a
    /// frame, and kept only when that voice lands: a voice that mints no
    /// clip discards its attempt whole, so a recording with no placeable
    /// voice adds no empty track. Its id is `next_id` off the trial at that
    /// moment, unchanged by a discarded attempt.
    static func addMicrophones(
        _ voices: [Voice], pictureStarts: [Ticks?]?, scope: UInt32?,
        to trial: inout ReelProject, ops: inout [ReelOp], notes: inout [String]
    ) throws -> (media: [UInt32?], clips: [UInt32?]) {
        precondition(
            pictureStarts.map { $0.count == voices.count } ?? true,
            "one picture start per voice")
        var media: [UInt32?] = []
        for voice in voices {
            if let mic = voice.descriptor {
                media.append(try addMedia(mic, to: &trial, ops: &ops))
            } else {
                media.append(nil)
            }
        }
        let none: [UInt32?] = voices.map { _ in nil }
        guard let starts = pictureStarts else { return (media, none) }
        var track: UInt32?
        var clips: [UInt32?] = []
        var floor: Ticks = 0
        for (k, voice) in voices.enumerated() {
            guard let id = media[k], let start = starts[k] else {
                clips.append(nil)
                continue
            }
            var attempt = trial
            var attemptOps: [ReelOp] = []
            let on: UInt32
            if let added = track {
                on = added
            } else {
                on = attempt.snapshot.nextId
                let addTrack = ReelOp.addTrack(index: 0, name: microphoneTrackName)
                guard let withTrack = try attempt.applying(addTrack.scoped(scope)).project
                else {
                    throw ReelCoreError(message: "A track for the microphone could not be added.")
                }
                attempt = withTrack
                attemptOps.append(addTrack)
            }
            guard
                let placed = try addMicrophoneClip(
                    id, on: on, pictureAt: start, offset: voice.offset, floor: floor,
                    scope: scope, to: &attempt, ops: &attemptOps, notes: &notes)
            else {
                clips.append(nil)
                continue
            }
            trial = attempt
            ops += attemptOps
            track = on
            clips.append(placed.id)
            floor = placed.end
        }
        return (media, clips)
    }

    /// One voice's clip on `track`, at `pictureAt − offset` and never below
    /// `floor` — 0 for the first voice, the previous voice's end after it.
    /// nil, with a sentence in `notes`, for a voice that gets no clip; the
    /// trial and the ops are advanced only for a clip returned.
    ///
    /// **The sign.** `offset` is the screen's did-start minus the
    /// microphone's, in ticks; positive means the picture began AFTER the
    /// microphone, so the microphone's content LEADS and its clip starts
    /// that much earlier than the picture's. R0 measured it centred near
    /// zero with a 35 ms scatter (road map 3, R0 q6b) and a different number
    /// at every resume (q7), and the landing applies each segment's measured
    /// number — never a constant, never the first segment's.
    ///
    /// **When that start is below the floor** — the picture at 0 with the
    /// microphone ahead of it, or a later voice whose picture began less
    /// than its offset after the previous voice ended — the clip cannot
    /// start there: below 0 there is no timeline, below the previous voice's
    /// end there is a clip, and placing it AT the floor would leave the
    /// voice LATE by the difference. So the head is trimmed off instead, and
    /// it stays one grouped edit: `add_clip` at the floor, `trim_start` to
    /// the landed start + head (the core sets the start there and advances
    /// `in` by the same amount — `core/src/edit_clip.rs`), `move_clip` back
    /// by what the trim advanced, read off the trimmed clip (the head, at
    /// an exact rate; at an inexact one the grid point nearest it). A
    /// `slip` would be the one-op spelling and cannot be used: the clip
    /// covers its whole media, so the slip's clamp reduces it to nothing.
    /// The head is the core's own snap of the shortfall
    /// (`ReelTime.snapToFrame`, the rounding every time argument gets), so a
    /// start within half a frame of the floor makes no trim and the two ops
    /// are not sent — the core's snap of that start lands it on the floor —
    /// while a start further below is trimmed rather than left to the snap,
    /// because the core would snap it to the frame BELOW the floor: at 0
    /// clamped up and late by a frame, above 0 a one-frame overlap the rule
    /// accepts as a transition. Limit: the grid is the picture's frame — at
    /// 60 fps 16.7 ms — so the alignment is exact to half a frame and no
    /// finer.
    ///
    /// **Every step is read back, and two things are decided by what comes
    /// back** (the R2 review). `trim_start` clamps its `to` at a frame
    /// before the clip's end, so a voice no longer than its head — an 80 ms
    /// file whose picture began 100 ms after it — used to be trimmed to a
    /// one-frame sliver and then moved back INTO the previous voice, which
    /// `move_clips` refused: `applying(_ ops:)` still answered non-nil (the
    /// add and the trim had changed something), the trial "succeeded", and
    /// the commit ran a refused op inside its undo step with the sliver
    /// sitting late. Now the trimmed clip's start is compared with the
    /// core's own snap of the requested `to`, and a start that is not it is
    /// the clamp: the voice is wholly under its head, mints NO clip, and its
    /// sentence names the file. And the moved clip must land exactly where
    /// the core's snap of the delta says, at or above the floor, or the
    /// throw names the file — a refused op can never ride a committed list.
    /// At an INEXACT rate the move's landing can be a tick under a floor
    /// that is a grid point (the delta and the trim round separately; grid
    /// points are not closed under addition), which the rule would accept
    /// and dress as a transition, so that one case is done once more a
    /// frame up with a frame more head: the content stays aligned to the
    /// tick, the voice starts a sub-frame gap after the previous one, and
    /// its first frame past the head is the price — the documented limit of
    /// such a rate, beside the pictures' own sub-frame gap.
    static func addMicrophoneClip(
        _ media: UInt32, on track: UInt32, pictureAt: Ticks, offset: Ticks, floor: Ticks,
        scope: UInt32?, to trial: inout ReelProject, ops: inout [ReelOp], notes: inout [String]
    ) throws -> ClipSnapshot? {
        let file = try mediaEntry(media, in: trial, scope: scope)
        let fps = try view(of: trial, scope: scope).snapshot.canvas.fps
        if let note = tooShortNote(file, at: fps) {
            notes.append(note)
            return nil
        }
        let start = pictureAt - offset
        let head = start < floor ? ReelTime.snapToFrame(floor - start, fps: fps) : 0
        guard head > 0 else {
            guard
                let placed = try placeClip(
                    media, on: track, at: max(start, floor), notBelow: floor, scope: scope,
                    to: &trial, ops: &ops)
            else {
                throw ReelCoreError(message: "\(file.path) could not be placed on its track.")
            }
            return placed
        }
        let frame = fps.frameDuration
        for (at, head) in [(floor, head), (floor + frame, head + frame)] {
            var attempt = trial
            var attemptOps: [ReelOp] = []
            guard
                let placed = try headTrimmed(
                    media, file: file, on: track, at: at, head: head, floor: floor, fps: fps,
                    scope: scope, to: &attempt, ops: &attemptOps)
            else {
                notes.append(underNote(file, head: head, floor: floor))
                return nil
            }
            if placed.start >= floor {
                trial = attempt
                ops += attemptOps
                return placed
            }
        }
        throw ReelCoreError(
            message: "\(file.path) could not be placed clear of the previous microphone clip.")
    }

    /// The dance once, on `trial`: the add at `at` (never under `floor`),
    /// the trim to the landed start + `head`, the move back by what the trim
    /// advanced. nil when the trim clamped — the voice is wholly under its
    /// head — with the trial left as it was; every other surprise is a
    /// throw naming the file. The clip returned may still sit a tick under
    /// the floor at an inexact rate, which the caller reads.
    static func headTrimmed(
        _ media: UInt32, file: MediaSnapshot, on track: UInt32, at: Ticks, head: Ticks,
        floor: Ticks, fps: Fps, scope: UInt32?, to trial: inout ReelProject, ops: inout [ReelOp]
    ) throws -> ClipSnapshot? {
        guard
            let added = try placeClip(
                media, on: track, at: at, notBelow: floor, scope: scope, to: &trial, ops: &ops)
        else {
            throw ReelCoreError(message: "\(file.path) could not be placed on its track.")
        }
        let trim = ReelOp.trimStart(clip: added.id, to: added.start + head)
        let promisedTrim = ReelTime.snapToFrame(added.start + head, fps: fps)
        guard let trimmed = try trial.applying(trim.scoped(scope)).project,
            try clip(added.id, in: trimmed, scope: scope).start == promisedTrim
        else { return nil }
        let advanced = promisedTrim - added.start
        let move = ReelOp.moveClip(clips: [added.id], delta: -advanced)
        let promisedStart = promisedTrim + ReelTime.snapToFrame(-advanced, fps: fps)
        guard let moved = try trimmed.applying(move.scoped(scope)).project else {
            throw ReelCoreError(
                message: "\(file.path) could not be moved back by its \(milliseconds(advanced)) ms head.")
        }
        let landed = try clip(added.id, in: moved, scope: scope)
        guard landed.start == promisedStart, landed.source.sourceIn == advanced else {
            throw ReelCoreError(
                message: "\(file.path) landed at \(landed.start) with \(landed.source.sourceIn) "
                    + "trimmed, not at \(promisedStart) with \(advanced).")
        }
        trial = moved
        ops += [trim, move]
        return landed
    }

    /// The sentence for a voice wholly under its head.
    private static func underNote(_ file: MediaSnapshot, head: Ticks, floor: Ticks) -> String {
        let clear = floor == 0 ? "the start of the timeline" : "the previous microphone clip"
        return "\(file.path) was added to the media list without a clip: less than a frame of "
            + "it would remain after the \(milliseconds(head)) ms head that keeps it clear of "
            + "\(clear)."
    }
}
// app/Sources/RecordingLanding+LeftOut.swift — a left-out segment's readable
// microphone in the landing (#181 item 2, spec §11 recording: "A left-out
// segment's readable microphone lands without its picture").
//
// A segment the walker left out (`RecordingResult.unreadable`) whose
// microphone file read carries it as `micDescriptor`, with `position` its
// place among the landed segments; `RecordingResult.stretches` lists the
// landed segments and those voices in recording order. Here is what the
// landing makes of that list: the PICTURE side as `PictureStretch`es — a
// landed segment's media, or a GAP the length of the voice snapped down to
// the frame, so the picture track stays empty there and the next picture
// starts at the slot's end — and the MICROPHONE side as `Voice`s, one per
// stretch, a voice-only one at offset 0 because no picture is there to align
// it to. `split` maps a per-stretch answer back to the `Placement`'s
// per-segment lists and its per-left-out-segment lists; `remainderStretches`
// is `remainderPlacement`'s clip-1 branch over the same list. With no
// left-out voice every stretch is a segment and every list is the one it was.
//
// In its own file because `RecordingLanding+Microphone.swift` stood at 381
// lines against the 400-line cap for a new file; `view` and `trimmed` are
// the base file's, internal for it.

import AppKit

extension RecordingLanding {
    /// One stretch of the picture track: a landed segment's media, placed
    /// by `placeBackToBack`, or a gap of `Ticks` it leaves empty.
    enum PictureStretch {
        case picture(UInt32)
        case gap(Ticks)
    }

    /// One stretch's microphone: its file when one landed (nil when none),
    /// and the offset its clip is placed by — a segment's measured
    /// `micOffset`, or 0 for a left-out voice.
    struct Voice {
        let descriptor: MediaDescriptor?
        let offset: Ticks
    }

    /// One `Voice` per stretch of `result`, in order.
    static func voices(of result: RecordingResult) -> [Voice] {
        result.stretches.map { stretch in
            switch stretch {
            case .segment(let k):
                return Voice(
                    descriptor: result.segments[k].micDescriptor,
                    offset: result.segments[k].micOffset)
            case .voiceOnly(let i):
                return Voice(descriptor: result.unreadable[i].micDescriptor, offset: 0)
            }
        }
    }

    /// One `PictureStretch` per stretch of `result`: segment `k`'s picture
    /// as `mediaIds[k]` (the ids its `add_media` answered, one per segment),
    /// and a left-out voice as a gap of `slotLength`, measured against the
    /// container `trial` and `scope` name.
    static func pictureStretches(
        of result: RecordingResult, mediaIds: [UInt32], in trial: ReelProject, scope: UInt32?
    ) throws -> [PictureStretch] {
        try result.stretches.map { stretch in
            switch stretch {
            case .segment(let k):
                return .picture(mediaIds[k])
            case .voiceOnly(let i):
                guard let voice = result.unreadable[i].micDescriptor else { return .gap(0) }
                return .gap(try slotLength(voice, in: trial, scope: scope))
            }
        }
    }

    /// The slot a voice-only stretch takes on the picture track: the file's
    /// length snapped DOWN to the container's frame — the length its clip
    /// takes (`SilenceDetector.snapDownToFrame`, the one Swift spelling of
    /// that snap, `rc_time_snap_to_frame` over the FFI) — and 0 for a file
    /// under a frame, which mints no clip and so takes no time.
    static func slotLength(_ voice: MediaDescriptor, in trial: ReelProject, scope: UInt32?) throws
        -> Ticks
    {
        let fps = try view(of: trial, scope: scope).snapshot.canvas.fps
        return max(0, SilenceDetector.snapDownToFrame(voice.duration, fps: fps))
    }

    /// A per-stretch list, `result.stretches`' order, split into one entry
    /// per landed segment and one per left-out segment (nil for a left-out
    /// segment with no voice, which has no stretch).
    static func split(_ list: [UInt32?], of result: RecordingResult)
        -> (segments: [UInt32?], leftOut: [UInt32?])
    {
        var segments: [UInt32?] = result.segments.map { _ in nil }
        var leftOut: [UInt32?] = result.unreadable.map { _ in nil }
        for (stretch, id) in zip(result.stretches, list) {
            switch stretch {
            case .segment(let k): segments[k] = id
            case .voiceOnly(let i): leftOut[i] = id
            }
        }
        return (segments, leftOut)
    }

    /// `remainderPlacement`'s clip-1 branch over the stretches: a left-out
    /// voice BEFORE clip 1 — the document at 0 — gets no start (media only)
    /// and `leadingVoiceNote`; clip 1 is its own stretch; everything after
    /// it goes on clip 1's track from clip 1's end by `placeBackToBack`, a
    /// voice's gap included, a refusal thrown by name (no two-try rule on a
    /// fresh document's one track). Answers one start and one picture clip
    /// id per stretch, for `addMicrophones` and `split`.
    static func remainderStretches(
        _ result: RecordingResult, after first: ClipSnapshot, mediaIds: [UInt32],
        firstPath: String, scope: UInt32?, to trial: inout ReelProject, ops: inout [ReelOp],
        notes: inout [String]
    ) throws -> (starts: [Ticks?], clips: [UInt32?]) {
        let stretches = result.stretches
        let lead = stretches.firstIndex(of: .segment(0)) ?? 0
        var starts: [Ticks?] = stretches.map { _ in nil }
        var clips: [UInt32?] = stretches.map { _ in nil }
        for case .voiceOnly(let i) in stretches[..<lead] {
            if let mic = result.unreadable[i].micDescriptor {
                notes.append(leadingVoiceNote(mic.path, before: firstPath))
            }
        }
        starts[lead] = first.start
        clips[lead] = first.id
        let rest = Array(
            try pictureStretches(of: result, mediaIds: mediaIds, in: trial, scope: scope)[
                (lead + 1)...])
        guard !rest.isEmpty else { return (starts, clips) }
        guard
            let placed = try placeBackToBack(
                rest, on: first.track, from: first.end, scope: scope, to: &trial, ops: &ops,
                notes: &notes)
        else {
            throw ReelCoreError(
                message: "The recording's later segments could not be placed after its first.")
        }
        for (k, landed) in placed.enumerated() {
            starts[lead + 1 + k] = landed.at
            clips[lead + 1 + k] = landed.clip?.id
        }
        return (starts, clips)
    }

    /// The sentence for a left-out voice recorded BEFORE a new project's
    /// first segment, which is the document at 0: there is no timeline
    /// before it, so the voice lands as media only.
    static func leadingVoiceNote(_ path: String, before first: String) -> String {
        "\(path) was added to the media list without a clip: it was recorded before \(first), "
            + "which starts the new project at 0."
    }
}
// app/Sources/RecordingLanding+VoiceOver.swift — where a finished VOICE-OVER
// goes (spec §11 recording, "A voice-over is a recording with no picture",
// #99).
//
// A voice-over is an ordinary `RecordingResult` whose every segment's
// `descriptor` is an `.m4a` (`isVoiceOver`). `placement(_:in:place:)` forwards
// it here after its live-edit guard, and the rule is not the picture rule:
// every file lands on ONE new BACK track named "Microphone" — where a screen
// recording's microphone lands — touching, from the playhead, in the one
// grouped edit both doors commit as "Add Recording". Never the front track,
// and never an existing Microphone track: no rule says which track is "the"
// voice track. The placing is `placeBackToBack`'s (`+Placing`), so every clip
// is read back and a file under a frame lands as media with its
// `tooShortNote`; the track is kept only when at least one clip landed on it.
//
// A NEW project needs nothing here: `ProjectDocument.untitled(around:)` makes
// the first file the document (audio-only, 1920×1080 at the chosen rate) and
// `remainderPlacement` puts the later files touching it on its one track.

import AppKit

extension RecordingLanding {
    /// PURE, main thread: the voice-over's ops and predicted ids. Every
    /// file's `add_media` in order (document-level, unscoped); then, with
    /// `place`, on a trial copy, `add_track` at index 0 named
    /// `microphoneTrackName` and every file back to back from the playhead
    /// on it. A refusal on that new, empty track is thrown by name. The
    /// track and its clips are kept only when at least one clip landed —
    /// every file under a frame adds media and notes alone, and then no
    /// `add_track` is even tried, so a document at the track cap does not
    /// throw for a track nothing would land on. `clipIds` has
    /// one entry per segment; the two `mic…` lists are all nil (a
    /// voice-over's voice IS its descriptor); the two left-out lists have
    /// one nil per `unreadable` entry. The ops come back unscoped, the
    /// container ops stamped by the caller's door as for any landing.
    static func voiceOverPlacement(
        _ result: RecordingResult, in document: ProjectDocument, place: Bool
    ) throws -> Placement {
        assert(Thread.isMainThread)
        let scope = document.scope
        var trial = document.project
        var ops: [ReelOp] = []
        var notes: [String] = []
        var mediaIds: [UInt32] = []
        for segment in result.segments {
            mediaIds.append(try addMedia(segment.descriptor, to: &trial, ops: &ops))
        }
        var clipIds: [UInt32?] = mediaIds.map { _ in nil }
        let fps = try view(of: trial, scope: scope).snapshot.canvas.fps
        let shortNotes = try mediaIds.map {
            tooShortNote(try mediaEntry($0, in: trial, scope: scope), at: fps)
        }
        let canLand = shortNotes.contains { $0 == nil }
        if place && !canLand {
            notes += shortNotes.compactMap { $0 }
        } else if place {
            var attempt = trial
            let track = attempt.snapshot.nextId
            let addTrack = ReelOp.addTrack(index: 0, name: microphoneTrackName)
            guard let withTrack = try attempt.applying(addTrack.scoped(scope)).project else {
                throw ReelCoreError(message: "A track for the voice-over could not be added.")
            }
            attempt = withTrack
            var attemptOps: [ReelOp] = [addTrack]
            guard
                let placed = try placeBackToBack(
                    mediaIds.map { PictureStretch.picture($0) }, on: track,
                    from: document.playhead, scope: scope, to: &attempt, ops: &attemptOps,
                    notes: &notes)
            else {
                throw ReelCoreError(
                    message: "The voice-over could not be placed on its new Microphone track.")
            }
            if placed.contains(where: { $0.clip != nil }) {
                trial = attempt
                ops += attemptOps
                clipIds = placed.map { $0.clip?.id }
            }
        }
        let none: [UInt32?] = mediaIds.map { _ in nil }
        let leftOut: [UInt32?] = result.unreadable.map { _ in nil }
        return Placement(
            ops: ops, mediaIds: mediaIds, clipIds: clipIds, micMediaIds: none, micClipIds: none,
            notes: notes, leftOutMicMediaIds: leftOut, leftOutMicClipIds: leftOut)
    }
}

// app/Sources/RecordingLanding+Remainder.swift — `untitled(around:)`'s
// remainder landing (camera-recording CR3-0): `remainderPlacement`
// (everything a fresh untitled document does not already hold), the names
// its undo step can take (`microphoneActionName`, `segmentsActionName`, and
// since CR3b `cameraActionName` and `cameraMicrophoneActionName`),
// `remainderActionName(for:)`, the rule choosing between them, and
// `unplacedNote`, the sentence for a file with no first
// clip to follow. A PURE MOVE out of `RecordingLanding+Microphone.swift` at
// the 400-line cap, landed alone before camera + screen grows it;
// `unplacedNote` stays `private`, because nothing else calls it. The voices
// it lands are `+Microphone`'s `addMicrophones`, its cameras `+Camera`'s
// `addCameras`, its stretches `+LeftOut`'s `remainderStretches`. Since road
// map creator-jobs CU3c (spec §11 CU-31 (c)) the remainder also carries the
// ripples a Separate recording with Show Clicks lands its screen clips with
// (`+Cursor`'s `addRipples`), and is named `ripplesActionName` when they are
// all it holds.

import AppKit

extension RecordingLanding {
    /// The undo step's name for `ProjectDocument.untitled(around:)`'s
    /// remainder edit when the remainder is a microphone ALONE — one segment
    /// with a voice. There the picture is the document — undoing the step
    /// removes the voice and keeps the picture — so a step called "Add
    /// Recording" would promise to take back what it cannot, and the Edit
    /// menu would read "Undo Add Recording" over a project the undo leaves
    /// with the recording in it. The `.document` landing keeps `actionName`:
    /// its one step really does add and remove both.
    static let microphoneActionName = "Add Microphone"

    /// The same step's name when the remainder holds more than a voice — a
    /// paused recording's later segments, with or without microphones.
    /// "Segments" and not "Recording" for the reason above: the FIRST
    /// segment is the document and stays under the undo; what the step takes
    /// back is the rest.
    static let segmentsActionName = "Add Recording Segments"

    /// The same step's name for ONE segment whose remainder is its camera
    /// beside the screen (spec §11 CAM-10 (4)): the picture is the
    /// document, and the step takes the camera back.
    static let cameraActionName = "Add Camera"

    /// …and for ONE segment whose remainder is its camera and a voice.
    static let cameraMicrophoneActionName = "Add Camera and Microphone"

    /// Which name `untitled(around:)`'s remainder edit takes. For ONE
    /// segment: with a camera beside the screen, "Add Camera and
    /// Microphone" when there is any voice and "Add Camera" when there is
    /// not (CAM-10 (4)); without one, "Add Microphone" for any voice — its
    /// own (R1's landing, R1's name) or a left-out segment's. With neither,
    /// the remainder can only be its ripples (CU-31 (c)): "Cursor Clicks".
    /// "Add Recording Segments" otherwise. A one-segment recording with no
    /// voice, no camera and no ripples has no remainder and no step, and the
    /// answer for it is never read.
    static func remainderActionName(for result: RecordingResult) -> String {
        if result.segments.count == 1 {
            let voice =
                result.segments[0].micDescriptor != nil
                || result.unreadable.contains(where: { $0.micDescriptor != nil })
            if result.segments[0].cameraDescriptor != nil {
                return voice ? cameraMicrophoneActionName : cameraActionName
            }
            if voice { return microphoneActionName }
            return ripplesActionName
        }
        return segmentsActionName
    }

    /// Everything a fresh untitled document does NOT already hold, for
    /// `ProjectDocument.untitled(around:)`, whose `makeProject` placed the
    /// FIRST segment's picture at 0 on track 1 before anything else could
    /// run: segments 2…n's media and their pictures on that same track from
    /// clip 1's end, then every segment's microphone by the floor rule. nil
    /// when there is nothing to add — one segment, no microphone, no camera
    /// and no ripples (`wantsRipples` with a cursor not in the picture, CU-31).
    /// `placement(_:in:place:)` cannot serve it — the first picture's
    /// `add_media` would be the documented identity and its `add_clip` at 0
    /// would meet its own clip on the front track, refuse, and put the whole
    /// sequence a SECOND time on a new track. The answer reads as a whole
    /// landing: `mediaIds[0]` and `clipIds[0]` name the picture the document
    /// holds.
    ///
    /// Clip 1 is the FIRST clip whose source is the first segment's media,
    /// and the later pictures go on ITS track from ITS end — read off the
    /// document, not assumed to be track 1 at 0. That is exact for the one
    /// caller: `makeProject` places exactly one clip. A document holding the
    /// same media in several clips has no single answer here, and this
    /// method does not pretend to one — it is `untitled(around:)`'s, not a
    /// general "add the rest of a recording to a document" op. The later
    /// pictures take no two-try rule: a refusal on a fresh document's one
    /// track is not a track choice to fall back from but something wrong
    /// with a file, and is thrown by name.
    ///
    /// **Without clip 1** — `makeProject` tolerates a first picture the core
    /// refuses (a media with no duration) and opens the file in the Media
    /// tab — nothing on the timeline says where the recording is, so the
    /// remainder lands as MEDIA ONLY, `place: false`'s shape, with a
    /// sentence per file in `notes`. The first shape here placed every
    /// voice against a picture at 0, R1's one-segment fallback, which with
    /// several voices stacked each one under the last (the floor rule
    /// trimming a whole voice off) — a wrong sound where a Media-tab list
    /// is at least an honest one.
    ///
    /// **A left-out segment's readable voice** (#181 item 2) is a stretch:
    /// after clip 1 a gap the later pictures skip and a voice at its start;
    /// BEFORE clip 1, which is the document at 0, media only with
    /// `leadingVoiceNote`; without clip 1, media only with `unplacedNote`.
    ///
    /// **A camera beside the screen** (spec §11 CAM-10 (4)) lands after the
    /// later pictures and before the voices, by `addCameras` against each
    /// segment's picture start — clip 1's included — on ONE new track in
    /// front of the pictures', laid out with its segment's picture; without
    /// clip 1, as media only with
    /// `unplacedNote`.
    ///
    /// **The ripples** (CU-31 (c)) go on clip 1 and the later pictures right
    /// after those are placed (`addRipples`); without clip 1 there are none.
    static func remainderPlacement(
        _ result: RecordingResult, in document: ProjectDocument
    ) throws -> Placement? {
        assert(Thread.isMainThread)
        let hasMicrophone = result.segments.contains { $0.micDescriptor != nil }
        let hasLeftOutVoice = result.unreadable.contains { $0.micDescriptor != nil }
        let hasCamera = result.segments.contains { $0.cameraDescriptor != nil }
        let more = result.segments.count > 1 || hasMicrophone || hasLeftOutVoice || hasCamera
        guard more || wantsRipples(result) else { return nil }
        let path = trimmed(result.descriptor.path)
        let snapshot = document.editedProject.snapshot
        guard let mediaId = snapshot.media.first(where: { $0.path == path })?.id else {
            throw ReelCoreError(message: "\(path) is not in the document's media list.")
        }
        let first = snapshot.clips.first { clip in
            if case .media(let id, _, _) = clip.source { return id == mediaId }
            return false
        }
        let scope = document.scope
        var trial = document.project
        var ops: [ReelOp] = []
        var notes: [String] = []
        var mediaIds = [mediaId]
        for segment in result.segments.dropFirst() {
            mediaIds.append(try addMedia(segment.descriptor, to: &trial, ops: &ops))
        }
        var starts: [Ticks?]?
        var clips: [UInt32?] = result.stretches.map { _ in nil }
        if let first = first {
            let placed = try remainderStretches(
                result, after: first, mediaIds: mediaIds, firstPath: path, scope: scope,
                to: &trial, ops: &ops, notes: &notes)
            starts = placed.starts
            clips = placed.clips
            try addRipples(
                clips.compactMap { $0 }, of: result, scope: scope, to: &trial, ops: &ops)
        } else {
            for segment in result.segments.dropFirst() {
                notes.append(unplacedNote(segment.descriptor.path, behind: path))
            }
            for segment in result.segments {
                if let camera = segment.cameraDescriptor {
                    notes.append(unplacedNote(camera.path, behind: path))
                }
            }
            for segment in result.segments {
                if let mic = segment.micDescriptor { notes.append(unplacedNote(mic.path, behind: path)) }
            }
            for left in result.unreadable {
                if let mic = left.micDescriptor { notes.append(unplacedNote(mic.path, behind: path)) }
            }
        }
        let cameras = try addCameras(
            result, screenStarts: starts.map { segmentStarts($0, of: result) },
            screenClips: split(clips, of: result).segments, scope: scope,
            to: &trial, ops: &ops, notes: &notes)
        let microphones = try addMicrophones(
            voices(of: result), pictureStarts: starts,
            scope: scope, to: &trial, ops: &ops, notes: &notes)
        // Let in by the ripples alone, and no clip took one: nothing to add.
        guard more || !ops.isEmpty else { return nil }
        let micMedia = split(microphones.media, of: result)
        let micClips = split(microphones.clips, of: result)
        return Placement(
            ops: ops, mediaIds: mediaIds, clipIds: split(clips, of: result).segments,
            micMediaIds: micMedia.segments, micClipIds: micClips.segments, notes: notes,
            leftOutMicMediaIds: micMedia.leftOut, leftOutMicClipIds: micClips.leftOut,
            cameraMediaIds: cameras.media, cameraClipIds: cameras.clips)
    }

    /// The sentence for a file `remainderPlacement` lands as media because
    /// the first segment's picture has no clip to follow.
    private static func unplacedNote(_ path: String, behind first: String) -> String {
        "\(path) was added to the media list without a clip: \(first) has no clip on the "
            + "timeline for it to follow."
    }
}
// app/Sources/RecordingLanding+Cursor.swift — the ripples a Separate
// recording with Show Clicks lands with (road map creator-jobs CU3c, spec §11
// CU-31 (c), CU-42).
//
// With Cursor Separate the stream draws no click ring, so Show Clicks means
// "land the screen clips with ripples on": ONE `set_video {cursor: {clicks:
// "ripple"}}` over the placed screen clips whose media's cursor file is not in
// the picture, inside the landing's one step. `placement` calls it right after
// `addSequence`, and `remainderPlacement` after the later pictures, with clip
// 1 among the clips. Like every step here the op is applied to the trial
// scoped, as the commit will, and comes back unscoped for the door to stamp.

import AppKit

extension RecordingLanding {
    /// The undo step's name for `untitled(around:)`'s remainder when the
    /// ripples are all it holds — the Cursor section's Clicks row's name.
    static let ripplesActionName = "Cursor Clicks"

    /// Whether the landing writes ripples: Show Clicks was on, the cursor was
    /// recorded Separate, and the recording has a picture.
    static func wantsRipples(_ result: RecordingResult) -> Bool {
        result.choice.showClicks && result.choice.effectiveCursor == .separate
            && !result.isVoiceOver
    }

    /// When `wantsRipples`, one `set_video` over those of `clips` whose media
    /// in `trial` has a cursor file not in the picture, applied to `trial` and
    /// appended to `ops`; nothing when none qualifies (a segment whose cursor
    /// file was not written has no cursor to ripple). A refusal adds nothing:
    /// the ripples never take the recording down with them.
    static func addRipples(
        _ clips: [UInt32], of result: RecordingResult, scope: UInt32?,
        to trial: inout ReelProject, ops: inout [ReelOp]
    ) throws {
        guard wantsRipples(result), !clips.isEmpty else { return }
        let media = trial.snapshot.media
        var rippled: [UInt32] = []
        for id in clips {
            let placed = try clip(id, in: trial, scope: scope)
            guard case .media(let source, _, _) = placed.source,
                let cursor = media.first(where: { $0.id == source })?.cursor,
                !cursor.inPicture
            else { continue }
            rippled.append(id)
        }
        guard !rippled.isEmpty else { return }
        let op = ReelOp.setVideo(
            clips: rippled, patch: VideoPatch(cursorPart: CursorPatch(clicks: .ripple)))
        guard let next = try trial.applying(op.scoped(scope)).project else { return }
        trial = next
        ops.append(op)
    }
}
// app/Sources/RecordingLanding+Placing.swift — one clip on the grid, asked
// of the core (road map 3, R2's toll): a PURE MOVE out of
// `RecordingLanding.swift` at the 400-line cap, holding `placeBackToBack`
// (a sequence of clips, each at the previous END as read back), `placeClip`
// (one `add_clip`, read back and stepped a frame up when the core snapped
// it under its floor — the inexact-rate rule the base file's header
// argues), `tooShortNote` (a file with no WHOLE frame inside it),
// `mediaEntry` and `milliseconds`. Every "what will the core snap this to"
// here is put to the core over the FFI — `ReelTime.snapToFrame` is
// `rc_time_snap_to_frame` — or read off a purely-applied result; nothing
// re-derives a frame in Swift, which is what makes the answers exact at
// 24981/1000 as at 30. Internal, not private, because the microphone file
// calls all of them and `private` does not cross a file.

import AppKit

extension RecordingLanding {
    /// `media` as touching clips on `track`: the first at `at`, each later
    /// one at the previous clip's END as read off the trial after its
    /// `add_clip` — never computed here, because a sum over descriptor
    /// durations would be off-grid. Each is placed by `placeClip`, which
    /// reads the landed clip back and steps a frame up when the core snapped
    /// it under the previous end (an inexact rate; the header says why), so
    /// two clips meet at one tick or leave a sub-frame gap and never overlap
    /// (`core/src/transition.rs`: `overlap_of` answers none at zero length).
    /// A picture too short for a frame — the core's `whole_media_length`
    /// answers an `Err` for it, and that `Err` used to take the whole list
    /// down — lands as media alone, with its sentence in `notes`, and
    /// the sequence carries on from the same point. nil when any `add_clip`
    /// refuses — the caller decides what a refusal means — and a throw is
    /// the core's own sentence. A `.gap` (a left-out segment's voice, #181
    /// item 2) places nothing: its `Landed` has no clip and starts where the
    /// sequence had reached, and the next picture starts the gap's length
    /// later. Answers one `Landed` per stretch, in order.
    static func placeBackToBack(
        _ stretches: [PictureStretch], on track: UInt32, from at: Ticks, scope: UInt32?,
        to trial: inout ReelProject, ops: inout [ReelOp], notes: inout [String]
    ) throws -> [Landed]? {
        var placed: [Landed] = []
        var at = at
        for stretch in stretches {
            let id: UInt32
            switch stretch {
            case .gap(let length):
                placed.append(Landed(clip: nil, at: at))
                at += length
                continue
            case .picture(let media):
                id = media
            }
            let file = try mediaEntry(id, in: trial, scope: scope)
            let fps = try view(of: trial, scope: scope).snapshot.canvas.fps
            if let note = tooShortNote(file, at: fps) {
                notes.append(note)
                placed.append(Landed(clip: nil, at: at))
                continue
            }
            guard
                let landed = try placeClip(
                    id, on: track, at: at, notBelow: at, scope: scope, to: &trial, ops: &ops)
            else { return nil }
            placed.append(Landed(clip: landed, at: landed.start))
            at = landed.end
        }
        return placed
    }

    /// `add_clip` of `media` on `track` at `at`, applied purely and READ
    /// BACK, and never landed below `floor` (≤ `at`): the core snaps the
    /// start to the nearest frame, and at an inexact canvas rate the
    /// nearest frame to a clip's end can be UNDER it — the end is a sum of
    /// two grid points, which is not one — so a landing under the floor is
    /// discarded whole and the add is made again at `floor` plus a frame,
    /// whose nearest frame is at or above the floor and within a frame of
    /// it. What comes back therefore satisfies `floor ≤ start ≤ at + frame`:
    /// touching, or a sub-frame gap at an inexact rate, never an overlap
    /// (which the rule would accept and dress as a transition). A landing
    /// outside that band after the second try is a throw, not a guess. nil
    /// is the core's refusal — an overlap the rule will not accept — and
    /// the op is appended and the trial advanced only for the clip returned.
    static func placeClip(
        _ media: UInt32, on track: UInt32, at: Ticks, notBelow floor: Ticks, scope: UInt32?,
        to trial: inout ReelProject, ops: inout [ReelOp]
    ) throws -> ClipSnapshot? {
        precondition(at >= floor, "a clip is asked for at or above its floor")
        let frame = try view(of: trial, scope: scope).snapshot.canvas.fps.frameDuration
        for requested in [at, floor + frame] {
            let op = ReelOp.addClip(track: track, media: media, at: requested)
            let id = trial.snapshot.nextId
            guard let next = try trial.applying(op.scoped(scope)).project else { return nil }
            let landed = try clip(id, in: next, scope: scope)
            if landed.start < floor { continue }
            guard landed.start <= at + frame else {
                throw ReelCoreError(
                    message: "Clip \(id) landed at \(landed.start), more than a frame past \(at).")
            }
            trial = next
            ops.append(op)
            return landed
        }
        throw ReelCoreError(
            message: "Clip \(trial.snapshot.nextId) could not be placed at or after \(floor).")
    }

    /// The sentence for a media the core cannot make a clip of, or nil: a
    /// timed media with no WHOLE frame inside it is an `Err` to
    /// `whole_media_length` (`core/src/edit_clip.rs`) — "no duration" at
    /// zero, "shorter than a frame" above it — and not a refusal, and R0 q7
    /// measured a real 2 ms microphone file. The test IS the core's: a clip
    /// takes the media's length snapped DOWN (spec §11), so the threshold
    /// here is `SilenceDetector.snapDownToFrame`, the one Swift spelling of
    /// that snap and itself `rc_time_snap_to_frame` over the FFI — exact at
    /// every rate, and nothing here re-derives a frame. An image has no such
    /// bound and gets the default length instead, which is why it is exempt.
    static func tooShortNote(_ file: MediaSnapshot, at fps: Fps) -> String? {
        guard file.kind != .image,
            SilenceDetector.snapDownToFrame(file.duration, fps: fps) <= 0
        else {
            return nil
        }
        return "\(file.path) is too short for a frame (\(milliseconds(file.duration)) ms) "
            + "and was added to the media list without a clip."
    }

    /// The media entry `id` names in `trial` — the document's one list, which
    /// a nest's view shares (`core/src/scope.rs`). An id the trial's own
    /// `add_media` answered and does not list is a throw.
    static func mediaEntry(_ id: UInt32, in trial: ReelProject, scope: UInt32?) throws
        -> MediaSnapshot
    {
        let container = try view(of: trial, scope: scope).snapshot
        guard let media = container.media.first(where: { $0.id == id }) else {
            throw ReelCoreError(message: "Media \(id) was added and is not listed.")
        }
        return media
    }

    /// A tick count as milliseconds to a tenth, for a note about a length
    /// under a frame — where `ReelTime.format`'s timecode would read
    /// `00:00:00:00` and say nothing.
    static func milliseconds(_ ticks: Ticks) -> String {
        String(format: "%.1f", Double(ticks) / (Double(ReelTime.perSecond) / 1000))
    }
}
