import AVFoundation
import AppKit

/// What a recording ENDS as — `StopReason`, `RecordingResult` and
/// `RecorderError` — the foot of `RecordingSetup.swift` moved whole, as a
/// pure move landed alone (road map 3, R2's toll), because that file stood
/// at 387 lines against the 400-line cap for a new file and the result
/// type is where R2's segments land. Values a probe can make, as before:
/// `tools/proof/recording_probe.py` constructs every one of them without a
/// stream. `RecordingSetup.swift` keeps what a recording IS before it
/// starts; `ScreenRecorder+Finishing.swift` is the one producer of a
/// `RecordingResult`; `RecordingLanding.swift` and the two doors are its
/// readers.

/// How the recording ended. `.stopped` is `ScreenRecorder.stop()`; the other
/// two are the stream delegate's `didStopWithError` codes: `.userStopped`
/// is −3817 (`SCStreamError.Code.userStopped`, the system's own menu-bar
/// indicator) and `.systemStopped` is −3821 (the code is spelled
/// `.systemStoppedStream`; a display that slept or went away) — and, while
/// PAUSED, any other stream stop as well, since nothing was writing
/// (`ScreenRecorder+Delegates.swift`).
enum StopReason: Equatable {
    case stopped
    case userStopped
    case systemStopped
}

/// One SEGMENT of a recording — the two files one stretch between a start
/// (or a resume) and a pause (or the stop) wrote, probed, and how they line
/// up (road map 3, decision 6: a paused recording is a sequence of files
/// over one stream, and every segment carries its OWN offset, because R0 q7
/// measured a different number for each resume).
struct RecordingSegment {
    /// The movie, probed through `MediaImporter.probe` (completion on main);
    /// for a voice-over (`RecordingResult.isVoiceOver`) that stretch's `.m4a`,
    /// with `micDescriptor` nil and `micOffset` 0.
    let descriptor: MediaDescriptor
    /// The `.m4a`, probed, when a microphone was chosen AND this segment's
    /// file landed; nil otherwise, and `micProblem` says which.
    let micDescriptor: MediaDescriptor?
    /// Screen did-start minus microphone did-start, in ticks, for THIS
    /// segment. POSITIVE means the picture began AFTER the microphone, so
    /// the microphone clip starts that much earlier than the picture's (or
    /// has its in point trimmed by it). Measured per segment, never a
    /// constant (R0 q6b: +11 ms mean, 35 ms scatter with the session
    /// started first; q7: −22 to +33 ms across resumes). 0 with no
    /// microphone.
    let micOffset: Ticks
    /// The screen's did-start, wall clock (its fallbacks are the call that
    /// asked for it, `ScreenRecorder+Finishing.swift`'s rule).
    let startedAt: Date
    /// Non-nil when a microphone was chosen but this segment's file did
    /// not land — it never started, the writer reported an error, the
    /// device went away, or the file would not probe (R1 review finding 0:
    /// a microphone problem does not fail a recording whose picture is on
    /// disk). The sentence names the file when one was left behind.
    /// `micDescriptor` is nil whenever this is set. For a voice-over it is
    /// set only on a segment whose writer stopped on its own (spec §11
    /// recording, "A voice-over is a recording with no picture").
    let micProblem: String?
    /// A camera beside the screen (spec §11 CAM-9): this segment's
    /// `(Camera).mov`, probed; nil without a camera, for a writer that took
    /// no buffer, and whenever `cameraProblem` is set.
    let cameraDescriptor: MediaDescriptor?
    /// The camera's first buffer minus the screen's start (E2, else E1,
    /// else the arrivals), in ticks; POSITIVE means the camera began after
    /// the screen. 0 without `cameraDescriptor`.
    let cameraOffset: Ticks
    /// This segment's camera file did not land — its writer failed or it
    /// would not probe — naming the file when it is on disk.
    let cameraProblem: String?
    /// Beside `cameraDescriptor` only: this segment's camera was placed by
    /// E1 because the frame watch could not go back on the stream at its
    /// resume (CAM-9 (6)), naming why.
    let cameraNote: String?
    /// This segment's cursor file, `<stem>.fjcursor` beside its movie (spec
    /// §11 CU-18); nil when none was written, and then `cursorProblem` says
    /// why (a session with no cursor capture writes none and says nothing).
    let cursorURL: URL?
    /// Why this segment has no cursor file, or what its file lacks (CU-12,
    /// CU-13, CU-14); never the recording's failure.
    let cursorProblem: String?
    /// The written file's `cursor_image` (`none` since CU-S1's verdict);
    /// nil without a file.
    let cursorImage: CursorImageMode?

    init(
        descriptor: MediaDescriptor, micDescriptor: MediaDescriptor?, micOffset: Ticks,
        startedAt: Date, micProblem: String? = nil, cameraDescriptor: MediaDescriptor? = nil,
        cameraOffset: Ticks = 0, cameraProblem: String? = nil, cameraNote: String? = nil,
        cursorURL: URL? = nil, cursorProblem: String? = nil, cursorImage: CursorImageMode? = nil
    ) {
        self.descriptor = descriptor
        self.micDescriptor = micDescriptor
        self.micOffset = micOffset
        self.startedAt = startedAt
        self.micProblem = micProblem
        self.cameraDescriptor = cameraDescriptor
        self.cameraOffset = cameraOffset
        self.cameraProblem = cameraProblem
        self.cameraNote = cameraNote
        self.cursorURL = cursorURL
        self.cursorProblem = cursorProblem
        self.cursorImage = cursorImage
    }

    /// This segment with its cursor fields set, every other field kept; `attached`, when given,
    /// is its descriptor's `cursor` (spec §11 CU-34 (c), (d)).
    func withCursor(
        url: URL?, problem: String?, image: CursorImageMode?, attached: MediaCursor? = nil
    ) -> RecordingSegment {
        var described = descriptor
        if let attached { described.cursor = attached }
        return RecordingSegment(
            descriptor: described, micDescriptor: micDescriptor, micOffset: micOffset,
            startedAt: startedAt, micProblem: micProblem, cameraDescriptor: cameraDescriptor,
            cameraOffset: cameraOffset, cameraProblem: cameraProblem, cameraNote: cameraNote,
            cursorURL: url, cursorProblem: problem, cursorImage: image)
    }
}

/// A segment whose MOVIE would not probe, left out of the recording (#97),
/// or a CLOSED segment whose writer failed after its stop, left out
/// unprobed (#181): the movie as named, the files it left on disk at settle
/// (movie, then microphone, each only if there), and the error `settle`
/// built for it — the writer's own sentence for the second.
/// `sentence` is what the panel's note and the tool's `note` say about it.
/// `micDescriptor` is its microphone file, probed, when it reads (#181 item
/// 2, spec §11 recording): the landing puts that voice in the picture's
/// slot. `position` is how many of `RecordingResult.segments` were recorded
/// before it — where that slot is among the landed segments.
struct UnreadableSegment {
    /// For a voice-over, the `.m4a` that would not probe.
    let moviePath: String
    let keptFiles: [String]
    let error: RecorderError
    let micDescriptor: MediaDescriptor?
    let position: Int

    init(
        moviePath: String, keptFiles: [String], error: RecorderError,
        micDescriptor: MediaDescriptor? = nil, position: Int = 0
    ) {
        self.moviePath = moviePath
        self.keptFiles = keptFiles
        self.error = error
        self.micDescriptor = micDescriptor
        self.position = position
    }

    var sentence: String {
        "A segment was left out. " + error.localizedDescription
            + (keptFiles.isEmpty
                ? " It left no file on disk."
                : " Its files are kept at " + keptFiles.joined(separator: ", ") + ".")
    }
}

/// What a camera recording records with (spec §11 CAM-3): the device's name,
/// the format it recorded at as `CameraDevices.spelled` writes it
/// (`1760x1328@30`), and `problem` — the sentence of a camera that stopped on
/// its own (a runtime error, an interruption, a disconnect), which ended a
/// camera recording with `stoppedBy` `.systemStopped` and, beside a screen
/// (CAM-9 (7)), ended only the camera's files; nil when it did not. `note`
/// is the warm-up's sentence when the stream had not reached the format's
/// rate by the bound and the recording began anyway (`CameraCapture.WarmUp`).
struct RecordingCamera: Equatable {
    let name: String
    let format: String
    var problem: String?
    var note: String?
}

/// What a recording ends as: its segments, in order — ONE for a recording
/// never paused — and what `RecordingLanding` turns into ops, one clip per
/// segment placed at the previous segment's end. `unreadable` is every
/// segment whose movie would not probe, or whose writer failed after the
/// segment closed (#181), left out of `segments` and named in
/// `unreadableNote` (#97); a recording with NO readable movie is a failure,
/// never a result.
///
/// There is deliberately no `micDescriptor` and no `micOffset` on the
/// result: those are a SEGMENT's, and a reader that compiled against a
/// first-segment convenience would be silently wrong for a paused
/// recording. `descriptor` and `startedAt` ARE the first segment's, because
/// "the recording's file" is one thing to the readers that use them — the
/// untitled document's source and name, the path a tool addresses that
/// document by.
struct RecordingResult {
    /// Never empty.
    let segments: [RecordingSegment]
    let choice: RecordingChoice
    let stoppedBy: StopReason
    /// A camera recording's camera (`isCamera`), or the camera recorded
    /// beside a screen (spec §11 CAM-9); nil for every other recording.
    let camera: RecordingCamera?

    /// The FIRST segment's movie.
    var descriptor: MediaDescriptor { segments[0].descriptor }
    /// The FIRST segment's screen did-start, wall clock.
    var startedAt: Date { segments[0].startedAt }
    /// A voice-over: the microphone alone, every segment's `descriptor` its
    /// `.m4a` (spec §11 recording, #99).
    var isVoiceOver: Bool { choice.source == .voiceOver }
    /// A camera alone (spec §11 CAM-3): every segment's `descriptor` is the
    /// camera's `.mov`, landed by the picture rule as a screen's is.
    var isCamera: Bool { choice.source == .camera }
    /// Every segment's microphone problem, in order, joined by a space; nil
    /// when no segment has one.
    var micProblem: String? {
        let problems = segments.compactMap { $0.micProblem }
        return problems.isEmpty ? nil : problems.joined(separator: " ")
    }
    /// How many times Pause was pressed — STORED and counted on the session,
    /// never `segments.count − 1`: a pause with no resume before the Stop
    /// leaves ONE file and was still a pause (the R2 review: it read 0).
    let pauses: Int
    /// The segments left out because their movie would not probe, or
    /// because their writer failed after the segment closed (#181), in
    /// segment order; empty when every movie read.
    let unreadable: [UnreadableSegment]
    /// Every left-out segment's sentence, joined by a space; nil when none.
    var unreadableNote: String? {
        unreadable.isEmpty ? nil : unreadable.map(\.sentence).joined(separator: " ")
    }

    /// The files on disk, for a sentence that sends a person to them: every
    /// segment's movie in order, comma-joined, then — when any landed —
    /// " and its microphone at <file>" for one microphone file or " and its
    /// microphone files at <a>, <b>" for several; then, for a camera beside
    /// the screen (spec §11 CAM-10 (8)), " and its camera at <file>" or " and
    /// its camera files at <a>, <b>" the same way. One shape for the panel's
    /// note and the tool's `savedButNotAdded`, so a three-segment failure
    /// names three files at both doors (the R2 review: the panel named one).
    var filesClause: String {
        let movies = segments.map { $0.descriptor.path }.joined(separator: ", ")
        let mics = segments.compactMap { $0.micDescriptor?.path }
        let cameras = segments.compactMap { $0.cameraDescriptor?.path }
        let clause: String
        switch mics.count {
        case 0: clause = movies
        case 1: clause = movies + " and its microphone at " + mics[0]
        default: clause = movies + " and its microphone files at " + mics.joined(separator: ", ")
        }
        switch cameras.count {
        case 0: return clause
        case 1: return clause + " and its camera at " + cameras[0]
        default: return clause + " and its camera files at " + cameras.joined(separator: ", ")
        }
    }

    /// Every segment's camera sentences beside the screen (spec §11 CAM-10
    /// (6)): its `cameraProblem`, then its `cameraNote`, segment by segment,
    /// joined by a space; nil when no segment has one.
    var cameraSegmentsNote: String? {
        let sentences = segments.flatMap { [$0.cameraProblem, $0.cameraNote].compactMap { $0 } }
        return sentences.isEmpty ? nil : sentences.joined(separator: " ")
    }

    /// Every segment's `cursorProblem` (spec §11 CU-18), in order, joined by a
    /// space; nil when no segment has one.
    var cursorSegmentsNote: String? {
        let problems = segments.compactMap { $0.cursorProblem }
        return problems.isEmpty ? nil : problems.joined(separator: " ")
    }

    init(
        segments: [RecordingSegment], choice: RecordingChoice, stoppedBy: StopReason,
        pauses: Int, unreadable: [UnreadableSegment] = [], camera: RecordingCamera? = nil
    ) {
        precondition(!segments.isEmpty, "a RecordingResult carries at least one segment")
        self.segments = segments
        self.choice = choice
        self.stoppedBy = stoppedBy
        self.pauses = pauses
        self.unreadable = unreadable
        self.camera = camera
    }

    /// ONE segment — R1's shape, kept so a single-segment construction (the
    /// probe's rows, a recording never paused) reads as it did; `pauses`
    /// defaults to 0 for it, since one file with no pause is what it means.
    init(
        descriptor: MediaDescriptor, micDescriptor: MediaDescriptor?, micOffset: Ticks,
        choice: RecordingChoice, startedAt: Date, stoppedBy: StopReason,
        micProblem: String? = nil, pauses: Int = 0
    ) {
        self.init(
            segments: [
                RecordingSegment(
                    descriptor: descriptor, micDescriptor: micDescriptor, micOffset: micOffset,
                    startedAt: startedAt, micProblem: micProblem)
            ], choice: choice, stoppedBy: stoppedBy, pauses: pauses)
    }
}

/// One stretch of the recording's timeline, in recording order: a landed
/// segment (an index into `segments`), or a left-out segment's readable
/// voice with no picture (an index into `unreadable`) — #181 item 2.
enum RecordingStretch: Equatable {
    case segment(Int)
    case voiceOnly(Int)
}

extension RecordingResult {
    /// Every landed segment and every left-out voice that reads, in the
    /// order they were recorded: before each segment `k`, the left-out
    /// entries at `position == k` with a microphone (in `unreadable`'s
    /// order), then the segment; after the last, those at `segments.count`.
    /// With no left-out voice it is `.segment(0)…` exactly, so every landing
    /// over it is the one before #181 item 2.
    var stretches: [RecordingStretch] {
        func voices(at k: Int) -> [RecordingStretch] {
            unreadable.indices.filter { unreadable[$0].position == k && unreadable[$0].micDescriptor != nil }
                .map { RecordingStretch.voiceOnly($0) }
        }
        var list: [RecordingStretch] = []
        for k in segments.indices {
            list += voices(at: k)
            list.append(.segment(k))
        }
        return list + voices(at: segments.count)
    }

    /// What a landing that SUCCEEDED says about each left-out voice it
    /// added, joined by a space; nil when no left-out segment's microphone
    /// read. Never said by a failed landing (`savedButNotAdded`,
    /// `failedToLand`), which `unreadableNote` alone serves.
    var leftOutVoiceNote: String? {
        let paths = unreadable.compactMap { $0.micDescriptor?.path }
        guard !paths.isEmpty else { return nil }
        return paths.map {
            "The left-out segment's microphone, \($0), was added to the project without its "
                + "picture."
        }.joined(separator: " ")
    }
}

/// `.busy` is `start()` while not idle, and nothing else answers it any
/// more: a `stop()` in any state joins the finishing already under way
/// (R1 review finding 1). `.notPaused` is `resume()` while not paused
/// (R2); `.alreadyPaused` is `pause()` while paused — its own sentence,
/// because "no recording is in progress" is false while `isRecording` is
/// true — and `.notRecording` is `pause()` idle, arming or finishing.
/// `.startTimedOut` is the arm ceiling and `.timedOut` the finish ceiling,
/// two sentences because they name two different waits (finding 5).
/// `.filesKept` wraps a failure reached once a file was on disk, so the
/// panel's note and the tool's error carry the path with no change on their
/// side (finding 6); with segments its `movie` and `microphone` strings are
/// comma-joined lists, and the one-file sentence is byte for byte R1's; an
/// EMPTY `movie` (no movie on disk) names the microphone files alone (B55).
/// `.cameraDevice` is the camera's `.microphoneDevice`: no such camera, or one
/// that cannot be recorded from (spec §11 CAM-3).
indirect enum RecorderError: Error, LocalizedError {
    case busy
    case notRecording
    case notPaused
    case alreadyPaused
    case startFailed(String)
    case finishFailed(String)
    case startTimedOut
    case timedOut
    case microphoneDevice(String)
    case cameraDevice(String)
    case filesKept(RecorderError, movie: String, microphone: String?)

    var errorDescription: String? {
        switch self {
        case .busy: return "A recording is already in progress."
        case .notRecording: return "No recording is in progress."
        case .notPaused: return "The recording is not paused."
        case .alreadyPaused: return "The recording is already paused."
        case .startFailed(let why): return why
        case .finishFailed(let why): return why
        case .startTimedOut:
            return "The recording did not start within \(Int(ScreenRecorder.armCeiling)) s."
        case .timedOut:
            return "The recording did not finish writing within "
                + "\(Int(ScreenRecorder.finishCeiling)) s."
        case .microphoneDevice(let why): return why
        case .cameraDevice(let why): return why
        case .filesKept(let inner, let movie, let microphone):
            let base = inner.errorDescription ?? "The recording failed."
            guard !movie.isEmpty else {
                return microphone.map { base + " The microphone is at \($0)." } ?? base
            }
            let clause = microphone.map { "; the microphone at \($0)" } ?? ""
            return base + " The recording is at \(movie)\(clause)."
        }
    }
}

import AVFoundation
import AppKit
import ScreenCaptureKit

/// File ▸ New Recording… (⌥⌘N) — the recorder's panel (road map 3, R1c).
/// One instance for the life of the process, `ExportQueueWindowController`'s
/// mould (`shared`, a private init, `isExcludedFromWindowsMenu`,
/// `isReleasedWhenClosed = false`), because a recording outlives documents
/// and the panel must exist with none open. The controls become one
/// `RecordingChoice`; Record hands it to `ScreenRecorder.shared`; the result
/// goes through `RecordingLanding` into a document or opens a new one. This
/// file is the window, its rows and its phases; `+Rows.swift` is what fills
/// the popups, and `+Choices.swift` turns them into a `RecordingChoice` and
/// back;
/// `+Recording.swift` is everything from Record pressed to the recording
/// running, `+Grants.swift` the three grants a press checks first and the
/// one place System Settings is opened for them, `+Landing.swift`
/// everything from the recording's end to the note that says where it
/// went, `+Picker.swift` the window picker, `+Pause.swift` the pause
/// and the resume, the hidden recording's one door and the phases drawn
/// (R2c), `+VoiceOver.swift` the Source row "Microphone Only" (#99),
/// `+Showing.swift` `show()`, the sync timer, `setNote` and the refit,
/// `+Camera.swift` the Source row "Camera", its popup, the Format popup and
/// the "Record the camera too" box (spec §11 CAM-5, CAM-6, CAM-11),
/// `+CameraPreview.swift` the camera's live preview in `CameraPreviewWell`
/// (CAM-7), `+Devices.swift` hot-plug: the device observers and the
/// popups rebuilt when a device comes or goes (CAM-8), `+Polish.swift` the
/// "When it lands:" boxes (road map creator-jobs CU10, spec §11 CU-102), and
/// `+CameraLanding.swift` the camera's Layout and cutout (CO8, spec §11 CO-82).
/// Fourteen files at the 400-line cap, and the crossing members are internal
/// for it, the tree's rule for a class split across files.
///
/// **It is an `NSPanel`, floating and NON-ACTIVATING**, and each of the four
/// window settings below is load-bearing. `.nonactivatingPanel` so Record,
/// and the countdown's Cancel, can be clicked with the application about to
/// be recorded still FRONTMOST — the panel is off screen once the recording
/// runs (below), so this is for the seconds before it, when activating
/// Frame Job would put its document windows over the target; `.floating` so
/// it stays above that thing; `hidesOnDeactivate = false`
/// because `NSPanel` defaults it TRUE (`PreviewWindowController` measured it)
/// and a recorder panel that vanished the moment the person switched to the
/// application they are about to record would be useless; and NO window
/// delegate — a delegate that answers nil for the undo manager is the trap
/// `PreviewWindowController` records, and here there is no document to
/// answer with. It persists nothing about its frame (the queue window's
/// posture: no autosave name, no defaults key for the harness to pin), and
/// centres itself once; a panel is picked up and put beside the recorded
/// window each time anyway. **Whatever it is refitted to stays on the
/// screen it is on** (`fitWindowToContent`, R1 review): the countdown
/// numeral grows the card 88 pt DOWNWARD — 130 with a note under it — from
/// a fixed top edge, and a panel parked at the bottom of a display, the
/// natural place for a recorder, used to put its Cancel button under the
/// Dock.
///
/// **Visibility during a recording** (decision 7, R2c): the panel orders
/// OUT at `recordingDidStart` for every source but Microphone Only and
/// Camera (below), and the status item is the
/// recording's whole chrome — Pause, Resume and Stop are its menu; File ▸
/// Stop Recording still stops. R1 kept a DISPLAY recording's panel up, its
/// filter excluding Frame Job (R0 q3), and hid only a PICKED window's; the
/// user asked for the dialog to go away whatever is recorded, and a panel
/// whose one live control was a Stop the menu bar also has earned nothing
/// on screen. It comes back after the landing ONLY when it was on screen
/// as the recording began (`showWhenLanded`, read at `recordingDidStart`)
/// AND the landing left a note (`revealIfNoted`, `+Landing.swift`): a stop
/// from the system's own indicator, a closed target, a microphone problem,
/// a refused resume, a failure. A clean recording lands and the panel
/// stays away, and a panel closed before the recording began stays closed
/// whatever the note; ⌥⌘N shows it again. `show()` BEEPS while
/// `hiddenForRecording` (R1 review) — the welcome window's button reaches
/// it — because a panel un-hidden into the recording would be in the file;
/// the quit guard goes through `revealControls()` instead (`+Pause.swift`).
/// **It takes key only from an active Frame Job** (spec §11, #137): shown from
/// the background it is ordered front without key, so Return stays with
/// the app in front. **A voice-over stays UP** (#99): nothing is filmed, so
/// the rows lock, the meter stays live, Record reads Stop with a Pause /
/// Resume button beside it; Close takes the panel away and the recording
/// carries on — the welcome button and the quit guard show the panel again,
/// and ⌥⌘N (File ▸ Stop Recording) and the status item stop it. **So does
/// a camera recording** (CAM-5), on the same terms: nothing on screen is
/// filmed.
///
/// Two limits of that chrome, accepted (R2 review). With the panel hidden
/// the status item is the ONLY Pause and Resume, and macOS drops a status
/// item that does not fit the menu bar — behind a notch, in a crowded bar
/// — so there Stop survives in the File menu and Pause and Resume do not.
/// And "●" and "❚❚" differ in width under `variableLength`, so the items to
/// the left of it shift by a few points at each pause and resume.
///
/// **Quit while recording, and the order AppKit asks in.**
/// `AppDelegate.applicationShouldTerminate` cancels a quit while
/// `ScreenRecorder.shared.isRecording` and calls `revealControls()` — the
/// status item's menu, opened, while this panel is hidden for its
/// recording; `show()` for any other (a tool's, which File ▸ Stop Recording
/// ends) — and it is a BACKSTOP: `NSDocumentController` reviews modified
/// documents FIRST, so the save sheet comes before the guard, and a target
/// document the review CLOSED lands as `.newProject` —
/// `RecordingLanding.resolve` looks the destination up by `recipeKey`,
/// never minted twice, so the miss is exact, and the landing's note says
/// the document was closed.
///
/// **Two Record Into rules.** The popup is built from `NSMenuItem`s carrying
/// each document's `recipeKey` in `representedObject` and is read from
/// `selectedItem`, never by index: `NSPopUpButton.addItem(withTitle:)`
/// REMOVES a same-titled row (phase 4's defect), and two untitled documents
/// read alike. And it follows the FRONT document until the person chooses a
/// row themselves (`chosenDestination`), re-synced by a one-second timer
/// while the panel is visible — rows compared before any rebuild, so a menu
/// the person has open is never rebuilt under the pointer — **and only while
/// the phase is idle** (`rebuildDestinations`, R1 review): from the press
/// of Record to the landing the rows are FROZEN at what the person saw when
/// they pressed it, whichever document comes to the front meanwhile, and
/// `landed()`'s own rebuild is what moves them again. The destination the
/// recording actually lands in was captured from the controls at the
/// countdown's end and cannot move either way; what the freeze buys is that
/// the row on screen and the destination in the choice agree.
///
/// Every choice persists under a `FrameJobRecording…` key (written on change,
/// read on show); the harness pins all eighteen on `FrameJobExportChoice`'s terms.
/// `.picked` is the one source that cannot persist — a filter is not a
/// value — so a reopened panel with a picked window keeps the row only while
/// the filter is still held; Microphone Only and Camera persist for the
/// session only (the camera itself is remembered, the row is not). "Record
/// the camera too" (CAM-11) is remembered across launches, and so is Record
/// shortcuts (road map creator-jobs CU6, spec §11 CU-62), off by default, and
/// Cursor (CU3c, spec §11 CU-36), whose `""` follows the source's default,
/// the three "When it lands:" boxes (CU10, spec §11 CU-102), on, on and off
/// when never set, and the camera's Layout and cutout (CO-82), Corner and off.
final class RecorderPanelController: NSWindowController {
    static let shared = RecorderPanelController()

    // MARK: - Defaults keys

    static let displayKey = "FrameJobRecordingDisplay"
    static let microphoneKey = "FrameJobRecordingMicrophone"
    static let systemAudioKey = "FrameJobRecordingSystemAudio"
    static let showClicksKey = "FrameJobRecordingShowClicks"
    static let rateKey = "FrameJobRecordingRate"
    static let sizeKey = "FrameJobRecordingSize"
    static let includeFrameJobWindowsKey = "FrameJobRecordingIncludeFrameJobWindows"
    static let cameraKey = "FrameJobRecordingCamera"
    static let cameraFormatKey = "FrameJobRecordingCameraFormat"
    /// "Record the camera too" (spec §11 CAM-11 (2)); an absent key reads as off.
    static let cameraBesideKey = "FrameJobRecordingCameraBeside"
    /// "Enhance the microphone when it lands" (spec §11 AU-69); an absent key reads as off.
    static let enhanceMicrophoneKey = "FrameJobRecordingEnhanceMicrophone"
    /// Record shortcuts (spec §11 CU-62); an absent key reads as off.
    static let keysKey = "FrameJobRecordingKeys"
    /// Cursor (spec §11 CU-36 (d)): `""` follows the source, else a `RecordingCursor` raw value.
    static let cursorKey = "FrameJobRecordingCursor"

    // MARK: - Metrics and vocabulary

    /// Wider than `sheetWidth`: the microphone row is a popup AND a 120 pt
    /// meter beside the 106 pt label column, which 420 cannot hold.
    static let cardWidth: CGFloat = 500
    static let controlWidth: CGFloat = 200
    /// The Source popup's last row, "Window…", by tag; display rows carry
    /// their `CGDirectDisplayID` in `representedObject`.
    static let windowTag = 1
    static let countdownSeconds = 3
    static let rates = [30, 60]
    /// The note under Record shortcuts (spec §11 CU-60, CU-62).
    static let recordShortcutsSentence =
        "Records each shortcut you press with ⌘ or ⌃, or ⌥ with an arrow, Delete, Return, Tab "
        + "or Esc, and when you type, never what you type. Nothing is recorded while an app "
        + "holds secure input."

    /// Where the panel is in a recording's life. `syncPhase()` draws it.
    enum Phase: Equatable {
        case idle
        case countdown(Int)
        case starting
        case recording
        case paused
        case stopping
        case landing
    }

    var phase: Phase = .idle {
        didSet { syncPhase() }
    }

    let recorder = ScreenRecorder.shared

    // The controls — internal rather than private because the recording flow
    // lives in an extension in another file, and `private` does not cross one.
    let sourcePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let includeFrameJobCheckbox = NSButton(
        checkboxWithTitle: "Include Frame Job windows", target: nil, action: nil)
    let cameraBesideCheckbox = NSButton(
        checkboxWithTitle: "Record the camera too", target: nil, action: nil)
    let cameraPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let formatPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let microphonePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let enhanceMicrophoneCheckbox = NSButton(
        checkboxWithTitle: "Enhance the microphone when it lands", target: nil, action: nil)
    let meterView = LevelMeterView(meter: ScreenRecorder.shared.meter)
    let systemAudioSwitch = NSSwitch()
    let showClicksSwitch = NSSwitch()
    /// Cursor (spec §11 CU-36): "Separate", "In the picture"; each item's
    /// `representedObject` its `RecordingCursor` raw value.
    let cursorPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let recordShortcutsCheckbox = NSButton(
        checkboxWithTitle: "Record shortcuts", target: nil, action: nil)
    let recordShortcutsNote = NSTextField(wrappingLabelWithString: "")
    /// "When it lands:" (spec §11 CU-102 (a), `+Polish.swift`).
    let polishBoxes = RecorderPolishBoxes()
    /// The camera's Layout and Remove-background box (spec §11 CO-82, `+CameraLanding.swift`).
    let cameraLanding = RecorderCameraLandingControls()
    let ratePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let sizePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let sizeNote = NSTextField(labelWithString: "")
    let destinationPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let countdownLabel = NSTextField(labelWithString: "")
    let noteLabel = NSTextField(wrappingLabelWithString: "")
    let statusLabel = NSTextField(labelWithString: "")
    let recordButton = AccentButton(
        title: "Record", symbol: "record.circle", fallback: "●",
        tooltip: "Start recording after a three-second countdown",
        action: #selector(record(_:)), fill: DS.meterClip)
    let closeButton = StickerButton(
        title: "Close", style: .secondary, target: nil, action: #selector(closePanel(_:)))
    let voiceOverPauseButton = StickerButton(
        title: "Pause", style: .secondary, target: nil, action: #selector(pauseButtonPressed(_:)))
    let cameraPreview = CameraPreviewWell()
    let card: NSView

    /// The picker's filter, held while the Source popup shows "Window
    /// (picked)". Cleared when a display row is chosen.
    var pickedFilter: SCContentFilter?
    var pickerObserved = false
    /// The Source row to fall back to when the picker is cancelled.
    var sourceBeforePick = 0
    /// nil follows the front document; set by the popup's own action.
    var chosenDestination: RecordingDestination?
    /// nil follows the source's default (CU-36 (d)); set only by the Cursor popup's own change.
    var cursorChosen: RecordingCursor? = nil
    /// A recording is running and the panel is off screen for it (`show()`
    /// beeps). Set at EVERY `recordingDidStart`, visible panel or not;
    /// `showWhenLanded` remembers whether it WAS visible, which is what
    /// `revealIfNoted` reads after the landing.
    var hiddenForRecording = false
    var showWhenLanded = false
    /// From `panelWillClose`'s first line until `show()`: the preview's
    /// step reads the panel as not visible, so a close never builds a capture.
    var panelClosing = false
    /// `AVCaptureDevice`'s two observers while the panel is up (`+Devices.swift`).
    var deviceObservers: [NSObjectProtocol] = []
    /// A device list may have changed (a notification, or observers newly added)
    /// and is not yet applied.
    var devicesPending = false
    /// The recorder's sentence for a resume it refused (`+Pause.swift`):
    /// REPLACED by each retry, cleared when a resume lands or the next
    /// countdown begins, one of the two parts the live note is rebuilt
    /// from, and a sentence the landing's note carries (`+Landing.swift`).
    var resumeProblem: String?
    /// Each press of Record is one attempt, numbered, and the completions
    /// the attempt hands out carry its number (`+Recording.swift`): a
    /// shareable-content answer from an attempt that was abandoned or timed
    /// out is told apart by it and ignored.
    var startGeneration = 0
    /// The current attempt has reached `ScreenRecorder.start` — from here
    /// the recorder's own arm ceiling is the bound and a Stop goes through
    /// `stop()`; before it, the lookup is the panel's to abandon.
    var launched = false
    var countdownTimer: Timer?
    var startTimer: Timer?
    var tickTimer: Timer?
    var landingTimer: Timer?
    var syncTimer: Timer?
    var landingAttempts = 0
    var statusItem: RecorderStatusItem?

    private init() {
        let panel = NSPanel(
            contentRect: NSRect(x: 0, y: 0, width: Self.cardWidth, height: 360),
            styleMask: [.titled, .closable, .nonactivatingPanel],
            backing: .buffered,
            defer: false)
        panel.title = "New Recording"
        panel.level = .floating
        // See the type doc: `NSPanel` defaults this to TRUE.
        panel.hidesOnDeactivate = false
        panel.isExcludedFromWindowsMenu = true
        panel.isReleasedWhenClosed = false
        panel.backgroundColor = DS.chromeBackground

        let content = NSStackView()
        card = makeSheetView(
            hint: "The recording is saved as a movie in the Frame Job Recordings folder and "
                + "added to the project you choose at the playhead, or opened as a new "
                + "project at the rate you pick.",
            content: content,
            buttonRow: makeButtonRow(
                cancel: closeButton, apply: recordButton, secondary: voiceOverPauseButton,
                leading: [statusLabel]),
            width: Self.cardWidth)
        super.init(window: panel)

        buildRows(into: content)
        // The card is a subview pinned at the top-left of a plain root, and
        // the window is sized to the card's fitting size by
        // `fitWindowToContent()` — never the window's content view itself,
        // whose autoresizing constraints would fight the card's own width and
        // vertical chain whenever a label appears or disappears.
        let root = NSView()
        root.wantsLayer = true
        card.translatesAutoresizingMaskIntoConstraints = false
        root.addSubview(card)
        NSLayoutConstraint.activate([
            card.topAnchor.constraint(equalTo: root.topAnchor),
            card.leadingAnchor.constraint(equalTo: root.leadingAnchor),
        ])
        panel.contentView = root
        recordButton.target = self
        closeButton.target = self
        voiceOverPauseButton.target = self

        rebuildSources()
        rebuildMicrophones()
        rebuildCameras()
        rebuildDestinations()
        restoreChoices()
        refreshSizeNote()
        syncPhase()
        panel.center()

        NotificationCenter.default.addObserver(
            self, selector: #selector(panelWillClose(_:)),
            name: NSWindow.willCloseNotification, object: panel)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("RecorderPanelController does not support NSCoder")
    }

    // MARK: - Actions

    @objc func controlChanged(_ sender: Any?) {
        if let sender = sender as? NSPopUpButton, sender === sourcePopup {
            if sender.selectedItem?.tag == Self.windowTag {
                presentPicker()
            } else {
                pickedFilter = nil
                sourcePopup.menu?.item(withTag: Self.windowTag)?.title = "Window…"
            }
        }
        if let sender = sender as? NSPopUpButton, sender === destinationPopup {
            chosenDestination = currentChoice().destination
        }
        if let sender = sender as? NSPopUpButton, sender === cameraPopup { rebuildCameraFormats() }
        if let sender = sender as? NSPopUpButton, sender === cursorPopup {
            cursorChosen = RecordingCursor(
                rawValue: cursorPopup.selectedItem?.representedObject as? String ?? "")
        }
        persistChoices()
        refreshSizeNote()
        syncControlsEnabled()
        syncCameraPreview()
    }

    @objc private func closePanel(_ sender: Any?) {
        window?.close()
    }

    /// A countdown must not go on in a panel nobody can see: closing cancels
    /// it, and a microphone or camera the countdown prepared is let go with it — said
    /// again here rather than left to `cancelCountdown`, because a panel
    /// closed during the microphone PROMPT (before any countdown) may also
    /// hold one, and an input left open past the panel is the leak the
    /// discard exists to close (R1 review). A close while `.starting` is a
    /// Stop (R2 review) — the attempt abandoned before `launch`, the
    /// recording stopped after it, `stopRecording`'s own two arms — because
    /// a start that ran on behind a closed panel would read `showWhenLanded`
    /// false and land every later note where nobody sees it. A RECORDING
    /// carries on — the status item and File ▸ Stop Recording can end it —
    /// and the sync timer stops until the next `show()`. `panelClosing` is
    /// set FIRST, so the phase change below steps the preview to off and
    /// never builds a capture (CAM-7 (5)), the device observers go (CAM-8 (1)),
    /// and the well is emptied last.
    @objc private func panelWillClose(_ note: Notification) {
        panelClosing = true
        switch phase {
        case .countdown: cancelCountdown()
        case .starting: stopRecording()
        default: break
        }
        recorder.discardPreparedMicrophone()
        recorder.discardPreparedCamera()
        stopObservingDevices()
        syncTimer?.invalidate()
        syncTimer = nil
        cameraPreview.showMessage(nil)
    }
}
import AVFoundation
import AppKit
import ScreenCaptureKit

/// Everything the recorder panel does from Record pressed to the recording
/// RUNNING (road map 3, R1c) — the countdown, the start, the stop —
/// `RecorderPanelController.swift`'s third file. The grants a press checks
/// first are `+Grants.swift`. The recording's END
/// and its landing are `+Landing.swift`, and the window picker is
/// `+Picker.swift`, both cut out along the lines `recordingEnded` and
/// `presentPicker` draw when the R1 review's fixes put this file past the
/// 400-line cap; the pause and the resume, and the phases drawn, are
/// `+Pause.swift` (R2c).
///
/// **Before the grants, the source** (R1 review): Record with the Source row
/// reading "Window…" and no picked filter refuses FIRST, by name, and starts
/// no countdown — `currentChoice()` would otherwise quietly fall back to the
/// main display and record the wrong thing. The picker is NOT presented from
/// the guard: a refusal that puts up a system UI is not a refusal. With
/// "Record the camera too" ticked (spec §11 CAM-11 (5)) no camera refuses
/// next, and the Camera grant is checked between Screen Recording and the
/// microphone; with it off the Camera grant is never read.
///
/// **The start is bounded and numbered** (R1 review). `.starting` used to
/// have no ceiling and no exit: `ScreenRecorder.shareableContent` can hold
/// its answer for tens of seconds on a locked console (measured ~37 s), and
/// a panel waiting on it showed "Starting…" with the button disabled and no
/// way back. Now each press of Record is one ATTEMPT with a number
/// (`startGeneration`), the lookup's completion carries the number and is
/// ignored once it is stale, and a one-shot timer at
/// `ScreenRecorder.armCeiling` fails the attempt with `.startTimedOut` while
/// the lookup is still pending. Once `launch` has handed the attempt to the
/// recorder its own arm ceiling is the bound (the same sentence, from the
/// start completion) and the panel's timer is cancelled, so the two cannot
/// both fire on one attempt.
///
/// **Stop while starting** (lane C's flag, closed by reading the seam):
/// after `launch` the recorder is arming and `stop()` is HELD — finishing
/// begins the moment the start lands, and the end arrives through the
/// session's `onFinish` like any other; a start that FAILS instead answers
/// the start completion alone, `onFinish` is never called for it, and
/// `startFailed` is the only thing that runs. Before `launch` there is
/// nothing to stop: `abandonStart` bumps the generation so the pending
/// answer is dropped, and the panel goes idle. Without that arm a Stop while
/// the lookup was pending left the panel at "Stopping…" for good, because
/// the answer then found the phase moved on and did nothing.
///
/// **The microphone is prepared at the countdown's start** (R1 review;
/// `ScreenRecorder+Microphone.swift` says why — `startRunning()`'s first-use
/// cost, up to 0.4 s of voice missing from the file) and discarded on cancel,
/// on close and on a refused start, so an input never stays open past the
/// recording it was for. **So is a camera's capture** (spec §11 CAM-5,
/// `ScreenRecorder+CameraPrepare.swift`), so CAM-3's warm-up runs through the
/// 3-2-1, and it is let go on the same four occasions. **The meter moves
/// during the countdown** (#98 c): `beginCountdown` arms the tick, which
/// through `.countdown` and `.starting` does nothing but
/// `publishMicrophoneLevel()`, read from the prepared session; the discard
/// publishes the silence. **The tick shows a microphone problem the moment
/// the recorder reports one**: the picture keeps recording, the meter goes
/// silent, and the note says so rather than leaving a dead bar.
///
/// **Two timers run in `.common` modes** — the countdown and the 30 Hz tick
/// — because a status item's menu runs the run loop in event-tracking mode
/// while it is open, and a default-mode timer stalls there: the elapsed
/// label in the menu bar froze at the one moment a person was looking at
/// it. `RecorderStatusItem`'s doc carries the same sentence from its side.
extension RecorderPanelController {
    /// The note for Record pressed over "Window…" with nothing picked.
    static let chooseWindowSentence = "Choose a window with Window… first, or pick a display."
    /// The note for a Stop that arrived before the recording had begun.
    static let abandonedSentence = "Stopped before the recording began; nothing was recorded."

    // MARK: - Record and Stop

    /// The Record button in every phase: start, cancel the countdown, or
    /// stop; a beep while the recorder is finishing or the panel is adding.
    @objc func record(_ sender: Any?) {
        switch phase {
        case .idle:
            beginIfGranted()
        case .countdown:
            cancelCountdown()
        case .recording, .paused, .starting:
            stopRecording()
        case .stopping, .landing:
            NSSound.beep()
        }
    }

    /// Stop, from the panel's button, the status item's menu or File ▸ Stop
    /// Recording. A recording the panel did not start (the `record_screen`
    /// tool's) is not this panel's to stop — `AppDelegate.newRecording`
    /// routes that one to the recorder directly — so anything but a panel
    /// recording beeps. Paused is stopped exactly as recording is: the
    /// recorder's `.paused` arm takes the same finishing path with the
    /// segment's output already closed — and the status item is FROZEN at
    /// the mark it shows, because the tick goes on through `.stopping` with
    /// `paused` false and would bring the coral dot back over a finish that
    /// captures nothing (R2 review; the footnote holds its mark the same
    /// way, `refreshStatusLabel`). While `.starting`: launched, the stop is
    /// held by the recorder and lands through `onFinish`; not yet, the
    /// attempt is abandoned (the type doc).
    func stopRecording() {
        switch phase {
        case .recording, .paused:
            statusItem?.freeze()
            phase = .stopping
            recorder.stop()
        case .starting where launched:
            phase = .stopping
            recorder.stop()
        case .starting:
            abandonStart()
        default:
            NSSound.beep()
        }
    }

    // MARK: - The grants

    private func beginIfGranted() {
        if voiceOverSelected { return beginVoiceOverIfGranted() }
        if cameraSelected { return beginCameraIfGranted() }
        if sourcePopup.selectedItem?.tag == Self.windowTag, pickedFilter == nil {
            setNote(Self.chooseWindowSentence)
            return
        }
        if cameraBesideSelected, selectedCameraID == nil {
            setNote(CameraDevices.noCameraSentence)
            return
        }
        guard checkScreenRecordingGrant(), checkInputMonitoringGrant(),
            !cameraBesideSelected || checkCameraGrant(), checkMicrophoneGrant()
        else { return }
        setNote("")
        beginCountdown()
    }

    // MARK: - The countdown

import AVFoundation
import AppKit
import ScreenCaptureKit

/// The half of screen recording a probe can call: values in, values out, no
/// framework object that needs a bundle (road map 3, R1a). What a recording
/// IS before it starts — the choice, where its files go and the two
/// ScreenCaptureKit configurations built from that choice (the two grants
/// it stands on are `RecordingGrant.swift`'s) — so that
/// `tools/proof/recording_probe.py` can read every field back from a bare
/// Mach-O that never starts a stream.
///
/// `ScreenRecorder.swift` (with `+Pause.swift`, `+Microphone.swift`,
/// `+Finishing.swift`, `+Delegates.swift` and `+Content.swift`) is the other
/// half: the class that owns the `SCStream`, one `SCRecordingOutput` per
/// SEGMENT (R2: a pause removes one and a resume adds the next) and, when a
/// microphone is chosen, the `AVCaptureSession` for the second file. The
/// result types a recording ends as — `StopReason`, `RecordingSegment`,
/// `RecordingResult`, `RecorderError` — are `RecordingResult.swift`, moved
/// off the foot of this file at the 400-line cap; they are still values a
/// probe can make.
///
/// Three R0 facts shape the configuration and are restated on the fields
/// they decide (`archive/roadmap-3.md`, "R0 — the answers"):
///
/// - **The microphone is a second file** (q2). `captureMicrophone` on the
///   stream writes ONE stereo track that is the SUM of system and microphone
///   sound, which is decision 5's bad case — so `make` never sets it, and
///   `RecordingChoice.microphone` names an `AVCaptureDevice` for
///   `ScreenRecorder`'s capture session instead.
/// - **`.best` does not scale by itself** (q4). `captureResolution = .best`
///   at the display's point size writes a point-sized file; pixels come only
///   when `width`/`height` are asked for in pixels, so `make` multiplies the
///   point size by the display's backing scale under `.best` itself.
/// - **Show Clicks needs BGRA** (q6a). `SCStream.h` says `showMouseClicks`
///   "currently applies when pixelFormat is set to BGRA" and a fresh
///   configuration reads `420v`, so `make` sets `REDACTED`
///   when the stream draws clicks and leaves the default alone otherwise —
///   measured, a recording output over a BGRA stream starts and writes. The
///   stream draws the pointer and its click ring only In the picture
///   (road map creator-jobs CU3c, spec §11 CU-31): with Separate, `make`
///   sets neither and keeps `420v`, and Show Clicks lands the screen clips
///   with ripples instead (`RecordingLanding+Cursor.swift`).

// MARK: - The choice

/// What is recorded. `.picked` is the panel's picker result, whose filter
/// is carried beside the choice (`ScreenRecorder.start` takes the filter as
/// its own argument), so the source enum never holds a framework object.
/// `.voiceOver` is the microphone alone, no picture (spec §11 recording, #99):
/// `ScreenRecorder.startVoiceOver` records it and `start` refuses it.
/// `.camera` is a camera alone, the device in `RecordingChoice.camera` (spec
/// §11 CAM-3): `ScreenRecorder.startCamera` records it and `start` refuses it,
/// while `start` records a camera beside a display, window or picked source (CAM-9).
enum RecordingSource: Equatable {
    case display(CGDirectDisplayID)
    case window(CGWindowID)
    case picked
    case voiceOver
    case camera
}

/// `nominal` records the display's POINT size, `best` its pixel size
/// (`RecordingConfiguration.make` does the multiply — R0 q4).
enum RecordingResolution: String, CaseIterable {
    case nominal
    case best
}

/// Where the recording lands when it stops. `.document` carries the target's
/// `recipeKey` rather than an `ObjectIdentifier`: an identifier of a closed
/// document is reused by the next one at the same address
/// (`RelinkSheetController.swift` says so), while a `recipeKey` is never
/// minted twice, so `RecordingLanding.resolve`'s miss → `.newProject`
/// fallback is exact.
enum RecordingDestination: Equatable {
    case newProject
    case document(recipeKey: Int)
}

/// Which keys a screen recording writes into its cursor files (road map creator-jobs CU6,
/// spec §11 CU-60, CU-62): none, or each shortcut spelled and a time-only mark for every other
/// key-down, under Input Monitoring. An enum so a later mode needs no rename; `record_screen`'s
/// `keys` spells it.
enum RecordingKeys: String, CaseIterable {
    case off
    case shortcuts
}

/// Where a screen recording's pointer goes (road map creator-jobs CU3c, spec §11 CU-31, CU-36):
/// `separate` — not in the movie, written to the cursor file for Frame Job to draw — or
/// `inPicture`, burned in by ScreenCaptureKit as before CU3c. `record_screen`'s `cursor` spells it.
enum RecordingCursor: String, CaseIterable {
    case separate
    case inPicture = "in_picture"

    /// CU-36 (b), (c), amended at CU0d: a window or picked recording's default. The
    /// quiet-machine re-run of CU-S2's window rows settled their anchor as E1, so it is
    /// `.separate`, as a display's is.
    static let windowDefault: RecordingCursor = .separate

    /// CU-36, amended at CU0d: `.separate` for a display, `windowDefault` (`.separate`) for a
    /// window or a picked source, and `.separate` for a voice-over or a camera alone, which have
    /// no pointer to draw.
    static func defaultFor(_ source: RecordingSource) -> RecordingCursor {
        switch source {
        case .display: return .separate
        case .window, .picked: return windowDefault
        case .voiceOver, .camera: return .separate
        }
    }
}

/// Every control of the recorder panel and every argument of
/// `record_screen`, as one value. `microphone` is an
/// `AVCaptureDevice.uniqueID`, nil for off; `rate` is 30 or 60 (a camera
/// recording's is its format's, `CameraDevices.canvasRate`). `camera` is an
/// `AVCaptureDevice.uniqueID`, set with `source` `.camera`, or beside a
/// display, window or picked source (CAM-9), and `cameraFormat` its format
/// as `CameraDevices.spelled` writes it, nil for Best and set only with
/// `camera` (spec §11 CAM-6).
struct RecordingChoice: Equatable {
    var source: RecordingSource = .display(CGMainDisplayID())
    var includeFrameJobWindows: Bool = false
    var microphone: String? = nil
    var systemAudio: Bool = true
    var showClicks: Bool = false
    var rate: Int = 60
    var resolution: RecordingResolution = .nominal
    var destination: RecordingDestination = .newProject
    var folder: URL = RecordingFiles.folder()
    var camera: String? = nil
    var cameraFormat: String? = nil
    /// Enhance Voice on the voice's clips after the landing; only with a microphone (AU-68, AU-69).
    var enhanceMicrophone: Bool = false
    /// Record shortcuts (spec §11 CU-62): only with a display, window or picked source.
    var keys: RecordingKeys = .off
    /// The Cursor row (spec §11 CU-36): nil follows the source's default.
    var cursor: RecordingCursor? = nil
    /// The polish on landing (spec §11 CU-100…CU-102): Auto Zoom, Add Shortcut Overlays and
    /// Speed Up Typing over the landed screen clips, each its own undo step after the landing.
    var autoZoom: Bool = false
    var shortcutOverlays: Bool = false
    var speedUpTyping: Bool = false
    /// The camera beside the screen's layout and its cutout on landing (spec §11 CO-80…CO-82).
    var cameraLayout: RecordingCameraLayout = .cornerSquare
    var cameraCutout: Bool = false

    /// The cursor this recording is made with: the choice, else the source's default.
    var effectiveCursor: RecordingCursor { cursor ?? .defaultFor(source) }
}

// MARK: - Where the files go

/// Decision 2 (road map 3 §0): a recording is ORIGINAL footage and lives in
/// `~/Movies/Frame Job Recordings/`, named by date and time — never in the
/// package (an untitled document has none) and never in the temporary
/// directory (where a cache is regenerable and footage would be lost). The
/// folder is created on demand, and `-RCRecordingFolder` overrides it the
/// way `-RCFFmpegPath` overrides the binary (`FFmpegRewrap.locate`), so a
/// proof can record into `tools/proof/work/` and delete it.
enum RecordingFiles {
    /// The launch-argument override, read from `UserDefaults.standard` so it
    /// works from the argument domain (`-RCRecordingFolder ~/x` on the
    /// command line, or a pinned volatile domain in a probe).
    static let folderDefaultsKey = "RCRecordingFolder"

    /// The default folder's name under `~/Movies`.
    static let folderName = "Frame Job Recordings"

    /// The folder a recording goes into: the override, tilde-expanded, when
    /// one is set; `~/Movies/Frame Job Recordings/` otherwise. Nothing is
    /// created here — `create(_:)` is called at the moment a recording has
    /// something to put in it, `AppSupport`'s rule.
    static func folder() -> URL {
        if let override = UserDefaults.standard.string(forKey: folderDefaultsKey),
            !override.isEmpty
        {
            return URL(
                fileURLWithPath: (override as NSString).expandingTildeInPath, isDirectory: true)
        }
        let movies =
            FileManager.default.urls(for: .moviesDirectory, in: .userDomainMask).first
            ?? FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(
                "Movies", isDirectory: true)
        return movies.appendingPathComponent(folderName, isDirectory: true)
    }

    /// `Screen Recording 2026-09-10 at 14.03.22` — the Screenshot app's
    /// spelling, in the machine's own time zone. The formatter is pinned to
    /// `en_US_POSIX` so a locale with another digit set or a 12-hour clock
    /// cannot change the name's shape; the seconds make a name unique across
    /// the app's own recordings and `uniqueURL` handles the rest.
    static func stem(at date: Date) -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = .current
        formatter.dateFormat = "'Screen Recording' yyyy-MM-dd 'at' HH.mm.ss"
        return formatter.string(from: date)
    }

    /// `Voice-over 2026-10-02 at 09.15.04` — a voice-over's file, `stem(at:)`'s
    /// spelling and pinning with its own lead word.
    static func voiceOverStem(at date: Date) -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = .current
        formatter.dateFormat = "'Voice-over' yyyy-MM-dd 'at' HH.mm.ss"
        return formatter.string(from: date)
    }

    /// `<stem>.<ext>` in `folder`, or `<stem> (2).<ext>`, `<stem> (3).<ext>`…
    /// while a file of that name exists — the Finder's own collision rule.
    static func uniqueURL(in folder: URL, stem: String, ext: String) -> URL {
        let manager = FileManager.default
        var candidate = folder.appendingPathComponent(stem).appendingPathExtension(ext)
        var counter = 2
        while manager.fileExists(atPath: candidate.path) {
            candidate = folder.appendingPathComponent("\(stem) (\(counter))")
                .appendingPathExtension(ext)
            counter += 1
        }
        return candidate
    }

    /// The microphone's own file, beside the movie: the movie's stem plus
    /// ` (Microphone)`, as `.m4a` (R0 q6b: `AVCaptureAudioFileOutput` writes
    /// one mono 48 kHz AAC track there), made unique the same way.
    static func microphoneURL(beside movie: URL) -> URL {
        let stem = movie.deletingPathExtension().lastPathComponent + " (Microphone)"
        return uniqueURL(in: movie.deletingLastPathComponent(), stem: stem, ext: "m4a")
    }

    /// Makes the folder, intermediate directories included. A folder that
    /// already exists is not an error.
    static func create(_ folder: URL) throws {
        try FileManager.default.createDirectory(
            at: folder, withIntermediateDirectories: true)
    }
}

// MARK: - The configurations

/// The two ScreenCaptureKit configurations a choice becomes. PURE — every
/// field is set from the arguments and read back by the probe — which is
/// what lets the `excludesCurrentProcessAudio` mutant be caught at all: it
/// is invisible over MCP (nothing plays during a headless recording) and
/// this is the only row that sees it.
enum RecordingConfiguration {
    /// System audio is asked for at 48 kHz stereo, the rate the tap and
    /// `Loudness.swift` already assume of every file.
    static let sampleRate = 48_000
    static let channelCount = 2

    /// `displayPointSize` and `scale` come from the caller, and the caller is
    /// `ScreenRecorder.start`, which reads them off the FILTER — its
    /// `contentRect` (points) and `pointPixelScale` — the one geometry
    /// source that also covers a picker-made filter (`SCDisplay`'s
    /// `width`/`height` are POINTS, R0 q4, and a display filter reports the
    /// display's point size and backing scale, a window filter the window's
    /// frame). The probe passes the numbers directly. `outputURL` is
    /// assigned before the output configuration is returned, and must stay
    /// so: reading `outputURL` off a fresh `SCRecordingOutputConfiguration`
    /// TRAPS (it imports non-optional and is nil underneath until assigned —
    /// the SDK scout's finding, exit 133).
    static func make(
        _ choice: RecordingChoice, displayPointSize: CGSize, scale: CGFloat, outputURL: URL
    ) -> (stream: SCStreamConfiguration, output: SCRecordingOutputConfiguration) {
        let stream = SCStreamConfiguration()
        // R0 q4: pixels are asked for, `.best` does not scale by itself.
        let factor: CGFloat = choice.resolution == .best ? max(scale, 1) : 1
        stream.width = Int((displayPointSize.width * factor).rounded())
        stream.height = Int((displayPointSize.height * factor).rounded())
        stream.captureResolution = choice.resolution == .best ? .best : .nominal
        stream.minimumFrameInterval = CMTime(value: 1, timescale: CMTimeScale(max(choice.rate, 1)))
        // CU-31: the pointer and its ring are the stream's only In the picture.
        let inPicture = choice.effectiveCursor == .inPicture
        stream.showsCursor = inPicture
        stream.showMouseClicks = choice.showClicks && inPicture
        // R0 q6a: the click circle draws only under BGRA; the default `420v`
        // is left alone when the stream draws no clicks, so an ordinary
        // recording's pixel path is byte for byte the spike's.
        if choice.showClicks && inPicture { stream.pixelFormat = REDACTED }
        stream.capturesAudio = choice.systemAudio
        stream.sampleRate = sampleRate
        stream.channelCount = channelCount
        // ALWAYS: the timeline can play while a recording runs and must not
        // be in it. `captureMicrophone` is deliberately never touched (R0
        // q2 — the microphone is a second file), so it keeps its default of
        // false, which the probe reads back on every row.
        stream.excludesCurrentProcessAudio = true

        let output = SCRecordingOutputConfiguration()
        output.outputURL = outputURL
        output.outputFileType = .mov
        // R0 q2: `availableVideoCodecTypes` is `[avc1, hvc1]` here and the
        // default is `avc1`; HEVC halves the file where the encoder offers it.
        output.videoCodecType =
            output.availableVideoCodecTypes.contains(.hevc) ? .hevc : .h264
        return (stream, output)
    }
}
