    // MARK: - Sources, microphones, destinations

    /// One row per `NSScreen`, by `localizedName`, carrying its
    /// `CGDirectDisplayID`; then "Window…", which presents the picker,
    /// "Camera" (`+Camera.swift`) and "Microphone Only" (`+VoiceOver.swift`).
    /// Built from `NSScreen` and NOT from `SCShareableContent`, because listing
    /// shareable content needs the Screen Recording grant and the panel must
    /// open without one. Reselects Microphone Only, Camera, the picked row or
    /// the current display.
    func rebuildSources() {
        let current = selectedDisplayID
        let voiceOver = voiceOverSelected
        let camera = cameraSelected
        let picked = pickedFilter != nil && sourcePopup.selectedItem?.tag == Self.windowTag
        sourcePopup.removeAllItems()
        for screen in NSScreen.screens {
            let item = NSMenuItem(title: screen.localizedName, action: nil, keyEquivalent: "")
            item.representedObject = NSNumber(value: Self.displayID(of: screen))
            sourcePopup.menu?.addItem(item)
        }
        sourcePopup.menu?.addItem(.separator())
        let window = NSMenuItem(
            title: picked ? "Window (picked)" : "Window…", action: nil, keyEquivalent: "")
        window.tag = Self.windowTag
        sourcePopup.menu?.addItem(window)
        let cameraRow = NSMenuItem(title: Self.cameraTitle, action: nil, keyEquivalent: "")
        cameraRow.tag = Self.cameraTag
        sourcePopup.menu?.addItem(cameraRow)
        let microphoneOnly = NSMenuItem(
            title: Self.microphoneOnlyTitle, action: nil, keyEquivalent: "")
        microphoneOnly.tag = Self.voiceOverTag
        sourcePopup.menu?.addItem(microphoneOnly)
        if voiceOver {
            sourcePopup.select(microphoneOnly)
        } else if camera {
            sourcePopup.select(cameraRow)
        } else if picked {
            sourcePopup.select(window)
        } else {
            selectDisplay(current)
        }
    }

    /// "Off", then every connected microphone (`connectedMicrophones()`, the
    /// session `ScreenRecorder.microphone(withID:)` asks, so a row here is a
    /// device the recorder can find), carrying its `uniqueID`.
    func rebuildMicrophones() {
        let current = microphonePopup.selectedItem?.representedObject as? String
        microphonePopup.removeAllItems()
        microphonePopup.menu?.addItem(NSMenuItem(title: "Off", action: nil, keyEquivalent: ""))
        for device in Self.connectedMicrophones() {
            let item = NSMenuItem(title: device.localizedName, action: nil, keyEquivalent: "")
            item.representedObject = device.uniqueID
            microphonePopup.menu?.addItem(item)
        }
        selectMicrophone(current)
    }

    /// "New Project" first, then every open document by `displayName` with
    /// its `recipeKey` in `representedObject`. The selection is the person's
    /// own choice while its document is still open, else the front document,
    /// else New Project.
    ///
    /// **Idle only** (R1 review). The rows used to follow the front document
    /// through a recording, so a person who pressed Record over "Untitled 2"
    /// and then clicked into "Untitled 3" to record it watched the row change
    /// to a document the recording was never going to land in — the choice
    /// was captured at the countdown's end. The guard is HERE rather than in
    /// the sync timer alone because the timer is not the only caller:
    /// `show()`, which the quit guard runs during a recording, rebuilds too.
    /// `landed()` sets the phase idle before its own rebuild, which is what
    /// moves the rows again.
    func rebuildDestinations() {
        guard phase == .idle else { return }
        let rows = Self.destinationRows()
        let listed = destinationPopup.itemArray.dropFirst().map { item in
            (item.title, (item.representedObject as? NSNumber)?.intValue ?? 0)
        }
        if destinationPopup.numberOfItems == 0 || !listed.elementsEqual(rows, by: { $0 == $1 }) {
            destinationPopup.removeAllItems()
            destinationPopup.menu?.addItem(
                NSMenuItem(title: "New Project", action: nil, keyEquivalent: ""))
            for (title, key) in rows {
                let item = NSMenuItem(title: title, action: nil, keyEquivalent: "")
                item.representedObject = NSNumber(value: key)
                destinationPopup.menu?.addItem(item)
            }
        }
        var wanted: Int?
        switch chosenDestination {
        case .some(.document(let key)) where rows.contains(where: { $0.1 == key }):
            wanted = key
        case .some(.newProject):
            wanted = nil
        default:
            chosenDestination = nil
            wanted = Self.frontDocument()?.recipeKey
        }
        let index =
            wanted.flatMap { key in
                destinationPopup.itemArray.firstIndex {
                    ($0.representedObject as? NSNumber)?.intValue == key
                }
            } ?? 0
        if destinationPopup.indexOfSelectedItem != index { destinationPopup.selectItem(at: index) }
    }

    static func destinationRows() -> [(String, Int)] {
        NSDocumentController.shared.documents.compactMap { $0 as? ProjectDocument }.map {
            ($0.displayName ?? "Untitled", $0.recipeKey)
        }
    }

    /// `currentDocument` first (nil when the app is not active), then the
    /// front of `orderedDocuments` — `AgentServer.target`'s rule.
    static func frontDocument() -> ProjectDocument? {
        if let current = NSDocumentController.shared.currentDocument as? ProjectDocument {
            return current
        }
        return NSApp.orderedDocuments.compactMap { $0 as? ProjectDocument }.first
    }

    static func displayID(of screen: NSScreen) -> CGDirectDisplayID {
        let key = NSDeviceDescriptionKey("NSScreenNumber")
        return (screen.deviceDescription[key] as? NSNumber)?.uint32Value ?? CGMainDisplayID()
    }

    var selectedDisplayID: CGDirectDisplayID {
        (sourcePopup.selectedItem?.representedObject as? NSNumber)?.uint32Value
            ?? CGMainDisplayID()
    }

    var selectedScreen: NSScreen? {
        guard sourcePopup.selectedItem?.tag != Self.windowTag, !voiceOverSelected, !cameraSelected
        else { return nil }
        let id = selectedDisplayID
        return NSScreen.screens.first { Self.displayID(of: $0) == id }
    }

    func selectDisplay(_ id: CGDirectDisplayID) {
        let index =
            sourcePopup.itemArray.firstIndex {
                ($0.representedObject as? NSNumber)?.uint32Value == id
            } ?? 0
        sourcePopup.selectItem(at: index)
    }

    func selectMicrophone(_ id: String?) {
        let index =
            id.flatMap { wanted in
                microphonePopup.itemArray.firstIndex { $0.representedObject as? String == wanted }
            } ?? 0
        microphonePopup.selectItem(at: index)
    }
}

        }
    }

    /// What one check decides (CU-101 (e)).
    enum Step: Equatable {
        case wait
        case run(Command, [UInt32])
        case drop
        case giveUp(Command)
    }

    /// One check every half second, the landing's (and Enhance's) own interval.
    static let checkInterval: TimeInterval = RecordingEnhance.checkInterval
    /// Past this since a command's clock started, it is given up on.
    static let waitLimit: TimeInterval = 300

    /// The commands `choice` asks for, always in `allCases` order.
    static func commands(of choice: RecordingChoice) -> [Command] {
        Command.allCases.filter { command in
            switch command {
            case .autoZoom: return choice.autoZoom
            case .shortcutOverlays: return choice.shortcutOverlays
            case .speedUpTyping: return choice.speedUpTyping
            }
        }
    }

    // MARK: - The screen

    /// Each segment's movie, the screen's files; none for a voice-over or a camera alone, whose
    /// segments are no screen. Pure; empty paths dropped, each path once.
    static func screenPaths(of result: RecordingResult) -> [String] {
        guard !result.isVoiceOver, result.choice.source != .camera else { return [] }
        var seen: Set<String> = []
        return result.segments.map { $0.descriptor.path }.filter {
            !$0.isEmpty && seen.insert($0).inserted
        }
    }

    /// Every clip of the open container whose media is one of `paths` AND has a cursor file,
    /// in id order. Main.
    static func screenClips(_ paths: [String], in document: ProjectDocument) -> [UInt32] {
        let wanted = Set(paths)
        guard !wanted.isEmpty else { return [] }
        let snapshot = document.editedProject.snapshot
        return snapshot.clips.filter { clip in
            guard let media = snapshot.media(for: clip) else { return false }
            return wanted.contains(media.path) && media.cursor != nil
        }.map(\.id).sorted()
    }

    // MARK: - Readiness

    /// Documents whose speech wait has started the cache pass, by `recipeKey` (CU-101 (c)).
    private static var cachesStarted: Set<Int> = []

    /// CU-101 (c). Auto Zoom and Add Shortcut Overlays need only the cursor files, which the
    /// caller has read. The speed-up is ready unless `SpeedUpTyping.resolve` answers `.waiting`;
    /// its first `.waiting` for the document starts `generateCaches()` (a pass that could not
    /// read a file is not retried until the next open). A throw counts as ready, so the run
    /// reports the refusal. Main.
    static func isReady(
        _ command: Command, clips: [UInt32], tracks: [UInt32: ReelCursor],
        speedUp: SpeedUpTypingSettings, in document: ProjectDocument
    ) -> Bool {
        guard command == .speedUpTyping else { return true }
        let snapshot = document.editedProject.snapshot
        let outcome: SpeedUpTypingOutcome
        do {
            outcome = try SpeedUpTyping.resolve(
                clips.compactMap { snapshot.clip($0) }, tracks: tracks,
                project: document.editedProject, cacheDirectory: document.cacheDirectory,
                settings: speedUp, from: nil, to: nil)
        } catch {
            return true
        }
        guard case .waiting = outcome else {
            cachesStarted.remove(document.recipeKey)
            return true
        }
        if cachesStarted.insert(document.recipeKey).inserted { document.generateCaches() }
        return false
    }

    /// The wait for `document` is over: a later wait starts the pass again. Main.
    static func forgetWait(_ document: ProjectDocument) {
        cachesStarted.remove(document.recipeKey)
    }

    /// CU-101 (e), in this order. Pure.
    static func decide(
        command: Command, clips: [UInt32], enhancing: Bool, ready: Bool, busy: Bool,
        elapsed: TimeInterval
    ) -> Step {
        if clips.isEmpty { return .drop }
        if enhancing { return .wait }
        if ready && !busy { return .run(command, clips) }
        if elapsed >= waitLimit { return .giveUp(command) }
        return .wait
    }

    // MARK: - Sentences (CU-101 (k))

    static func noScreenSentence(_ c: Command) -> String {
        "No screen clip with a cursor file landed on the timeline, so \(c.title) did not run."
    }

    static func notReadySentence(_ c: Command, tool: Bool) -> String {
        let why =
            c == .speedUpTyping
            ? "its speech was not detected within 5 minutes."
            : "the project was busy for 5 minutes."
        let way =
            tool
            ? " Call \(c.rawValue) with its clips."
            : " Select its clips and choose \(c.menuPath)."
        return "\(c.title) did not run on the recording: " + why + way
    }

    static func stoppedSentence(_ c: Command) -> String {
        "record_screen was stopped before \(c.title) ran, so it did not run."
    }

    /// The panel box's tooltip (CU-102 (a)), naming the step.
    static func tooltip(_ c: Command) -> String {
        "After the recording lands, run \(c.menuPath) on its screen clips as its own undo step, "
            + "\"\(c.title)\"."
    }
}
import AppKit

/// The recorder panel's polish follow (road map "creator-jobs" CU10, spec §11 CU-101 (f)…(i)):
/// a repeating timer per LANDING — never joined with another, unlike Enhance's — in the run
/// loop's DEFAULT mode, so a drag (tracking mode) holds it. Each firing decides for the first
/// command still to run; the follow ends FIRST, its timer invalidated and its entry removed, on
/// `.drop`, on `.giveUp`, before the last run, or when the cursor files fail to read, and then
/// the step acts. A refusal from one run moves on to the next command, whose clock starts then.
///
/// The panel's settings are what each menu door would use (CU-101 (g)): Auto Zoom's remembered
/// sheet values with Zoom on typing on whenever the files hold typing, the overlays' defaults
/// and Speed Up Typing's remembered sheet values. Nothing here asks: a plan with no ops and a
/// `.drop` are quiet, and a refusal, a give-up or a read failure is said at the inspector's foot
/// (`projectDocumentDidRefuse`), with no beep and no sheet (CU-101 (h)). A timer is not an
/// AppKit event, so every commit is `performGroupedEdit`.
extension RecordingPolish {
    /// One landing's follow.
    private final class Follow {
        weak var document: ProjectDocument?
        let paths: [String]
        let scope: UInt32?
        var commands: [Command]
        var started = Date()
        var enhancing = false
        /// The cursor files, by media id, once read; `reading` while a read is out.
        var tracks: [UInt32: ReelCursor]?
        var reading = false
        var timer: Timer?

        init(document: ProjectDocument, paths: [String], scope: UInt32?, commands: [Command]) {
            self.document = document
            self.paths = paths
            self.scope = scope
            self.commands = commands
        }
    }

    /// The follows under way, by a number minted per landing.
    private static var follows: [Int: Follow] = [:]
    private static var minted = 0

    /// The panel's landing hands its result here once it has committed (after Enhance's
    /// follow). A no-op unless the choice asks for a command. Main.
    static func follow(_ result: RecordingResult, in document: ProjectDocument) {
        let asked = commands(of: result.choice)
        guard !asked.isEmpty else { return }
        minted += 1
        let id = minted
        let follow = Follow(
            document: document, paths: screenPaths(of: result), scope: document.scope,
            commands: asked)
        follows[id] = follow
        // `scheduledTimer` adds it in the DEFAULT mode: it waits out a drag.
        follow.timer = Timer.scheduledTimer(withTimeInterval: checkInterval, repeats: true) {
            [weak document] timer in
            guard let document else {
                timer.invalidate()
                follows[id] = nil
                return
            }
            tick(id, document)
        }
    }

    /// True while any follow of `document` runs. Main.
    static func isPending(_ document: ProjectDocument) -> Bool {
        follows.values.contains { $0.document === document }
    }

    /// One firing. Main.
    private static func tick(_ id: Int, _ document: ProjectDocument) {
        guard let follow = follows[id], let command = follow.commands.first else {
            return end(id, document)
        }
        let clips = screenClips(follow.paths, in: document)
        // CU-101 (a): the clock restarts when Enhance Voice's follow ends.
        let enhancing = RecordingEnhance.isPending(document)
        if follow.enhancing && !enhancing { follow.started = Date() }
        follow.enhancing = enhancing
        let media = mediaIDs(clips, in: document)
        if !clips.isEmpty, !follow.reading,
            follow.tracks.map({ !media.isSubset(of: Set($0.keys)) }) ?? true
        {
            read(id, follow, clips, in: document)
        }
        let window = RecorderPanelController.editor(of: document)?.view.window
        let busy =
            RecordingEnhance.isBusy(document, scope: follow.scope) || window == nil
            || window?.attachedSheet != nil
        let ready =
            follow.tracks.map { tracks in
                media.isSubset(of: Set(tracks.keys))
                    && isReady(
                        command, clips: clips, tracks: tracks,
                        speedUp: SpeedUpTypingSettings.remembered(.standard), in: document)
            } ?? false
        let step = decide(
            command: command, clips: clips, enhancing: enhancing, ready: ready, busy: busy,
            elapsed: Date().timeIntervalSince(follow.started))
        switch step {
        case .wait:
            return
        case .drop:
            end(id, document)
        case .giveUp(let given):
            end(id, document)
            refuse(given, notReadySentence(given, tool: false), in: document)
        case .run(let ran, let ids):
            follow.commands.removeFirst()
            follow.started = Date()
            if follow.commands.isEmpty { end(id, document) }
            if let reason = run(ran, clips: ids, tracks: follow.tracks ?? [:], in: document) {
                refuse(ran, reason, in: document)
            }
        }
    }

    /// The media ids of `clips`. Main.
    private static func mediaIDs(_ clips: [UInt32], in document: ProjectDocument) -> Set<UInt32> {
        let snapshot = document.editedProject.snapshot
        return Set(clips.compactMap { snapshot.clip($0).flatMap { snapshot.media(for: $0)?.id } })
    }

    /// The clips' cursor files read on a global queue, once; a failure ends the follow and is
    /// said under the command it was read for. Main.
    private static func read(
        _ id: Int, _ follow: Follow, _ clips: [UInt32], in document: ProjectDocument
    ) {
        let snapshot = document.editedProject.snapshot
        let files: [UInt32: URL]
        do {
            files = try AutoZoom.cursorFiles(clips.compactMap { snapshot.clip($0) }, in: snapshot)
        } catch {
            return failRead(id, follow, error, in: document)
        }
        follow.reading = true
        DispatchQueue.global(qos: .userInitiated).async {
            let read = Result { try AutoZoom.readTracks(files) }
            DispatchQueue.main.async { [weak document] in
                follow.reading = false
                guard let document, follows[id] === follow else { return }
                switch read {
                case .success(let tracks): follow.tracks = tracks
                case .failure(let error): failRead(id, follow, error, in: document)
                }
            }
        }
    }

    private static func failRead(
        _ id: Int, _ follow: Follow, _ error: Error, in document: ProjectDocument
    ) {
        let command = follow.commands.first ?? .autoZoom
        end(id, document)
        refuse(command, error.localizedDescription, in: document)
    }

    private static func end(_ id: Int, _ document: ProjectDocument) {
        follows[id]?.timer?.invalidate()
        follows[id] = nil
        forgetWait(document)
    }

    // MARK: - The three runs

    /// Plans `command` over `clips` and commits it as one grouped step; nil when it applied or
    /// had nothing to do, else the sentence to say. Main.
    private static func run(
        _ command: Command, clips ids: [UInt32], tracks: [UInt32: ReelCursor],
        in document: ProjectDocument
    ) -> String? {
        let snapshot = document.editedProject.snapshot
        let clips = ids.compactMap { snapshot.clip($0) }
        do {
            switch command {
            case .autoZoom:
                var settings = AutoZoomSettings.remembered(.standard)
                settings.typing = AutoZoom.hasTyping(tracks)
                let plan = try AutoZoom.plan(
                    clips, tracks: tracks, project: document.editedProject, settings: settings,
                    from: nil, to: nil)
                guard !plan.ops.isEmpty else { return nil }
                document.performGroupedEdit(AutoZoom.actionName, plan.ops)
            case .shortcutOverlays:
                let planned = try ShortcutOverlays.prepared(
                    document, clips: ids, tracks: tracks, settings: ShortcutOverlaySettings(),
                    from: nil, to: nil)
                guard !planned.plan.ops.isEmpty else { return nil }
                document.performGroupedEdit(ShortcutOverlays.actionName, planned.plan.ops)
            case .speedUpTyping:
                return try speedUp(clips, tracks: tracks, in: document)
            }
        } catch {
            return error.localizedDescription
        }
        return nil
    }

    /// CU-101 (i): the panel cannot ask Set Speed, so a speed-up that would leave a clip's audio
    /// out is not applied and its note is the refusal; otherwise one grouped step, the captions
    /// it re-times riding in it.
    private static func speedUp(
        _ clips: [ClipSnapshot], tracks: [UInt32: ReelCursor], in document: ProjectDocument
    ) throws -> String? {
        let outcome = try SpeedUpTyping.resolve(
            clips, tracks: tracks, project: document.editedProject,
            cacheDirectory: document.cacheDirectory,
            settings: SpeedUpTypingSettings.remembered(.standard), from: nil, to: nil)
        guard case .planned(let speechOps, let plan) = outcome else {
            return notReadySentence(.speedUpTyping, tool: false)
        }
        guard !plan.ops.isEmpty else { return nil }
        let step = CaptionRetime.withRetime(
            SpeedUpTyping.actionName, speechOps + plan.ops, on: document.editedProject)
        let crossing =
            SpeedAudioDrop.mayCross(step.ops)
            ? SpeedAudioDrop.crossing(applying: step.ops, to: document.editedProject) : []
        guard crossing.isEmpty else { return SpeedAudioDrop.note(crossing) }
        document.performGroupedEdit(step.name, step.ops)
        return nil
    }

    /// A refusal of `command` at the inspector's foot; no beep (CU-101 (h)).
    private static func refuse(_ command: Command, _ reason: String, in document: ProjectDocument) {
        NotificationCenter.default.post(
            name: .projectDocumentDidRefuse, object: document,
            userInfo: ["refusal": ReelRefusal(op: command.rawValue, reason: reason)])
    }
}

import AppKit

/// "Enhance the microphone when it lands" (road map "audio" AP6 part 3, spec
/// §11 AU-68, AU-69): Enhance Voice run over a finished recording's VOICE
/// clips as a follow-up to the landing — never part of it. The landing commits
/// at once and is unchanged (`RecordingLanding`, `untitled(around:)`, the step
/// names, the notes); Enhance follows as its own undo step, "Enhance Voice",
/// once the voice's loudness and speech caches exist, because neither can
/// exist before the media is in a project.
///
/// The values and the pure decision are here: which files are the voice
/// (`voicePaths`), which clips they became (`voiceClips`), whether those are
/// measured (`isAnalysed`) and whether the document is in a state to take an
/// edit (`isBusy`), and `decide`. The two doors share them: the panel through
/// `follow` — a repeating timer per landing, in the run loop's DEFAULT mode
/// (the landing's retry trick: a drag runs the loop in tracking mode, so the
/// timer waits for it) — and `record_screen {enhance}` through
/// `AgentServer.landAndEnhance`, which polls `decide` from the server thread.
///
/// **The follow ends before anything is shown.** On any step but `.wait` the
/// timer is invalidated and the landing's pending entry removed FIRST, then
/// the step acts (`tick`): Cancel on the Measuring Sound sheet, no outcome or
/// a stale answer can never leave a timer that puts the sheet back up, and
/// `isPending` never depends on the sheet.
enum RecordingEnhance {
    /// One check every half second, the landing's own retry interval.
    static let checkInterval: TimeInterval = RecorderPanelController.landingRetryInterval
    /// Past this since the landing, a voice still unmeasured is given up on.
    static let waitLimit: TimeInterval = 300

    static let notReadyHead =
        "Enhance Voice did not run on the recording: its microphone was not ready to measure "
        + "within 5 minutes."
    static let notReadySentence = notReadyHead + " Select its clip and choose Clip ▸ Enhance Voice."
    /// The tool's `.giveUp` sentence: the same head, a tool's way out.
    static let notReadyToolSentence = notReadyHead + " Call enhance_voice with its clips."
    static let noVoiceSentence =
        "No microphone clip landed on the timeline, so there was nothing to enhance."
    /// The panel box's tooltip (AU-69 (a)), naming AU-68's step.
    static let boxTooltip =
        "After the recording lands, run Clip ▸ Enhance Voice on the microphone's clip as its own "
        + "undo step, \"Enhance Voice\", once its sound has been analysed."

    /// What one check decides (AU-68 (d)).
    enum Step: Equatable {
        case wait
        case enhance([UInt32])
        case drop
        case giveUp
    }

    // MARK: - The voice

    /// The recording's voice files: each segment's microphone file, each
    /// left-out segment's readable microphone file, and for a voice-over each
    /// segment's own file — never the picture, the camera or the system audio.
    /// None without a microphone. Pure; empty paths dropped, each path once.
    static func voicePaths(of result: RecordingResult) -> [String] {
        guard result.choice.microphone != nil else { return [] }
        var paths = result.segments.compactMap { $0.micDescriptor?.path }
        paths += result.unreadable.compactMap { $0.micDescriptor?.path }
        if result.isVoiceOver { paths += result.segments.map { $0.descriptor.path } }
        var seen: Set<String> = []
        return paths.filter { !$0.isEmpty && seen.insert($0).inserted }
    }

    /// Every clip in the open container whose media is one of the voice
    /// files, in clip-id order. Main, after the landing's commit.
    static func voiceClips(of result: RecordingResult, in document: ProjectDocument) -> [UInt32] {
        let paths = Set(voicePaths(of: result))
        guard !paths.isEmpty else { return [] }
        let snapshot = document.editedProject.snapshot
        return snapshot.clips.filter { clip in
            snapshot.media(for: clip).map { paths.contains($0.path) } ?? false
        }.map(\.id).sorted()
    }

    /// The clips still in the open container. Main.
    static func present(_ clips: [UInt32], in document: ProjectDocument) -> [UInt32] {
        let snapshot = document.editedProject.snapshot
        return clips.filter { snapshot.clip($0) != nil }
    }

    /// Each clip's media has a current loudness cache, and its speech saved,
    /// or a current speech cache, or no speech model at all (AU-68 (b)). False
    /// for no clips, a missing file or no cache folder. Main.
    static func isAnalysed(_ clips: [UInt32], in document: ProjectDocument) -> Bool {
        guard !clips.isEmpty, let cacheDir = document.cacheDirectory else { return false }
        let snapshot = document.editedProject.snapshot
        for id in clips {
            guard let clip = snapshot.clip(id), let media = snapshot.media(for: clip),
                let url = mediaURL(for: media)
            else { return false }
            let stamp = MediaImporter.CacheStamp.stamp(for: media, url: url)
            guard MediaImporter.loudnessIsCurrent(for: media, stamp: stamp, in: cacheDir) else {
                return false
            }
            guard media.speech != nil
                || MediaImporter.speechIsCurrent(for: media, stamp: stamp, in: cacheDir)
                || !SileroVAD.isAvailable
            else { return false }
        }
        return true
    }

    /// A drag in progress, or the open container is not the landing's. The
    /// panel adds its own window test in `tick`. Main.
    static func isBusy(_ document: ProjectDocument, scope: UInt32?) -> Bool {
        document.isLiveEditing || document.scope != scope
    }

    /// AU-68 (d), in this order. Pure.
    static func decide(clips: [UInt32], analysed: Bool, busy: Bool, elapsed: TimeInterval) -> Step {
        if clips.isEmpty { return .drop }
        if analysed && !busy { return .enhance(clips) }
        if elapsed >= waitLimit { return .giveUp }
        return .wait
    }

    // MARK: - The panel's follow

    /// One landing's follow: its document, its clips, the scope it landed in,
    /// when, and the timer.
    private final class Follow {
        weak var document: ProjectDocument?
        var clips: [UInt32]
        var scope: UInt32?
        var started: Date
        var timer: Timer?

        init(document: ProjectDocument, clips: [UInt32], scope: UInt32?) {
            self.document = document
            self.clips = clips
            self.scope = scope
            self.started = Date()
        }
    }

    /// The follows under way, by the document's `recipeKey` (never minted
    /// twice). A second landing into a document with a follow under way joins
    /// it: its clips are added and the clock and scope start again.
    private static var follows: [Int: Follow] = [:]

    /// The panel's landing hands its result here once it has committed. A
    /// no-op unless the choice asked for it. Main.
    static func follow(_ result: RecordingResult, in document: ProjectDocument) {
        guard result.choice.enhanceMicrophone else { return }
        let clips = voiceClips(of: result, in: document)
        let key = document.recipeKey
        if let pending = follows[key] {
            pending.clips = Array(Set(pending.clips + clips)).sorted()
            pending.scope = document.scope
            pending.started = Date()
            return
        }
        let follow = Follow(document: document, clips: clips, scope: document.scope)
        follows[key] = follow
        // `scheduledTimer` adds it in the DEFAULT mode: it waits out a drag.
        follow.timer = Timer.scheduledTimer(withTimeInterval: checkInterval, repeats: true) {
            [weak document] timer in
            guard let document else {
                timer.invalidate()
                follows[key] = nil
                return
            }
            tick(document)
        }
    }

    /// True only while a follow's timer runs for `document`. Main.
    static func isPending(_ document: ProjectDocument) -> Bool {
        follows[document.recipeKey] != nil
    }

    /// The timer of `document`'s follow, nil with none — what the probe reads
    /// back after a step (P5). Main.
    static func timer(of document: ProjectDocument) -> Timer? {
        follows[document.recipeKey]?.timer
    }

    /// One firing: decide, and on any step but `.wait` end the follow FIRST
    /// (the type doc), then act. Main.
    static func tick(_ document: ProjectDocument) {
        guard let follow = follows[document.recipeKey] else { return }
        let clips = present(follow.clips, in: document)
        let window = RecorderPanelController.editor(of: document)?.view.window
        let busy =
            isBusy(document, scope: follow.scope) || window == nil || window?.attachedSheet != nil
        let step = decide(
            clips: clips, analysed: isAnalysed(clips, in: document), busy: busy,
            elapsed: Date().timeIntervalSince(follow.started))
        guard step != .wait else { return }
        end(follow, key: document.recipeKey)
        switch step {
        case .enhance(let ids):
            guard let window else { return refuse(notReadySentence, in: document) }
            AudioMeasureDoor.enhanceLanded(document: document, clips: ids, window: window)
        case .giveUp:
            refuse(notReadySentence, in: document)
        case .drop, .wait:
            break
        }
    }

    private static func end(_ follow: Follow, key: Int) {
        follow.timer?.invalidate()
        follows[key] = nil
    }

    /// A refusal of `enhance_voice` at the inspector's foot; no beep (AU-68 (e)).
    static func refuse(_ reason: String, in document: ProjectDocument) {
        NotificationCenter.default.post(
            name: .projectDocumentDidRefuse, object: document,
            userInfo: [
                "refusal": ReelRefusal(op: AudioMeasureDoor.Command.enhanceVoice.tool, reason: reason)
            ])
    }
}
