import ScreenCaptureKit

/// Every screen recording's cursor file (road map creator-jobs CU1b1, spec §11 CU-11…CU-13,
/// CU-18): the segments' header and opening geometry, the capture's start with segment 0 open,
/// and the walker's cursor step, which writes one `<stem>.fjcursor` beside each landed movie
/// (`CursorFileWriter`, CU-15). `CursorCapture.swift` is the capture itself.
///
/// **The anchor is E1** (CU-12): a segment's times count from its screen did-start's host time,
/// stamped on every segment by `+Delegates.swift`; E2 is never used for a cursor file. A landed
/// segment with no E1 gets no file. **The geometry** comes from the frame watch (CU-13); a watch
/// that could not go on the stream (at the start, with no camera, or at the segment's resume)
/// leaves the file only its opening geometry, and the segment says so. **A cursor failure never
/// fails or reorders a segment** (CU-14): the walker's order is movie → microphone → camera →
/// cursor, and this step always hands its segment on. **Keys** (road map creator-jobs CU6, spec
/// §11 CU-60, CU-61): with Record shortcuts on, the capture's key tap writes each shortcut and
/// a time-only typed mark into the open segment; `recordsKeys` is what the status item's
/// keyboard mark reads.
extension ScreenRecorder {
    /// MAIN. Whether the running session's cursor capture has a key tap (spec §11 CU-61).
    var recordsKeys: Bool { session?.cursor?.recordsKeys ?? false }

    /// The header and opening geometry every segment's file starts from (CU-13), before any
    /// frame: `scale_factor` the filter's `pointPixelScale`; `content_scale` the stream's
    /// configured pixel width ÷ (scale factor × point width); `content_rect` (0, 0, the point
    /// size × content scale); `screen_rect` the source's frame — `CGDisplayBounds` for a
    /// display, the window list's `kCGWindowBounds` for a window (the filter's `contentRect`
    /// when the list has none, whose origin may be window-local rather than global points
    /// until the first frame's geometry replaces it), the filter's `contentRect` for a picked
    /// source. The header's
    /// `pixels_per_point` is the configured width ÷ the point width; `in_picture` the choice's
    /// (spec §11 CU-31: true only In the picture, where the stream burns the pointer in);
    /// `cursor_image` none (CU-S1).
    static func cursorStart(
        filter: SCContentFilter, choice: RecordingChoice, stream: SCStreamConfiguration
    ) -> CursorSegmentStart {
        let points = filter.contentRect.size
        let width = Double(max(stream.width, 1))
        let height = Double(max(stream.height, 1))
        let scaleFactor = positive(Double(filter.pointPixelScale))
        let pixelsPerPoint = positive(points.width > 0 ? width / Double(points.width) : 1)
        let contentScale = positive(
            points.width > 0 ? width / (scaleFactor * Double(points.width)) : 1)
        let source: CursorSourceKind
        let displayID: UInt32?
        let frame: CGRect
        switch choice.source {
        case .display(let id):
            source = .display
            displayID = id
            frame = CGDisplayBounds(id)
        case .window(let id):
            source = .window
            displayID = nil
            frame = windowBounds(id) ?? filter.contentRect
        case .picked, .voiceOver, .camera:
            source = .picked
            displayID = nil
            frame = filter.contentRect
        }
        let geometry = CursorGeometry(
            screenRect: frame,
            contentRect: CGRect(
                x: 0, y: 0, width: Double(points.width) * contentScale,
                height: Double(points.height) * contentScale),
            contentScale: contentScale, scaleFactor: scaleFactor)
        return CursorSegmentStart(
            inPicture: choice.effectiveCursor == .inPicture, source: source,
            displayID: displayID, sourceFrame: frame,
            pointSize: points, pixelsPerPoint: pixelsPerPoint,
            contentSize: CursorPixelSize(
                width: min(Int(width), 16384), height: min(Int(height), 16384)),
            cursorImage: .none, geometry: geometry)
    }

    /// What a Separate segment's no-file sentences end with (spec §11 CU-31 (d)): the stream drew
    /// no pointer, so without the file the pointer is nowhere.
    static let cursorSeparateLost =
        " The pointer is not in the movie either: it was recorded Separate."

    /// A segment's `cursorProblem` once its file was attempted: the writer's sentence when it
    /// has one (no file was kept), with `cursorSeparateLost` when `separate`; else, when the
    /// frames could not be watched, CU-13's sentence naming the movie and the reason (a file
    /// exists, so it is the same for both choices); else nil.
    static func cursorProblem(
        writer: String?, watchLost: String?, movieName: String, separate: Bool = false
    ) -> String? {
        if let writer { return separate ? writer + cursorSeparateLost : writer }
        guard let watchLost else { return nil }
        return "The cursor file for \(movieName) has only the geometry the screen had when it "
            + "began: its frames could not be watched (\(watchLost)), so a move or resize of "
            + "what was recorded after that is not in it."
    }

    /// CU-12's sentence for a landed segment with no E1, with `cursorSeparateLost` when
    /// `separate` (CU-31 (d)).
    static func cursorNoAnchorProblem(movieName: String, separate: Bool = false) -> String {
        "The cursor file for \(movieName) was not written: the screen never reported its start, "
            + "so its times have nothing to count from." + (separate ? cursorSeparateLost : "")
    }

    /// MAIN, from `launchScreen`: segment 0 opened, then the poll and the monitors started.
    /// Nothing for a session without a capture.
    func startCursorCapture() {
        guard let current = session, let cursor = current.cursor, let start = current.cursorStart
        else { return }
        cursor.openSegment(0, start)
        cursor.start()
    }

    /// The walker's cursor step for segment `index`, after its camera's: the buffer closed
    /// with the movie's track size and E1, written beside the movie on the capture's queue,
    /// and `landed` handed to `then` on main with its cursor fields. A session without a
    /// capture hands `landed` on unchanged.
    func saveCursor(
        _ done: Session, at index: Int, _ landed: RecordingSegment,
        then: @escaping (RecordingSegment) -> Void
    ) {
        guard let cursor = done.cursor else { return then(landed) }
        let segment = done.segments[index]
        let movie = segment.movieURL
        let name = movie.lastPathComponent
        let separate = done.choice.effectiveCursor == .separate
        guard let host = segment.screenHost else {
            return then(
                landed.withCursor(
                    url: nil,
                    problem: Self.cursorNoAnchorProblem(movieName: name, separate: separate),
                    image: nil))
        }
        let watchLost = segment.cursorWatchProblem ?? done.cursorWatchLost
        let size = CursorPixelSize(
            width: landed.descriptor.width, height: landed.descriptor.height)
        cursor.closeSegment(index, movieSize: size, anchor: CursorAnchor(kind: .e1, host: host)) {
            body in
            var url: URL?
            var writer: String?
            if let body {
                do {
                    url = try CursorFileWriter.write(body, forMovie: movie)
                } catch let problem as CursorFileProblem {
                    writer = problem.message
                } catch {
                    writer = "The cursor file for \(name) was not written: "
                        + error.localizedDescription
                }
            } else {
                writer = "The cursor file for \(name) was not written: no cursor was captured "
                    + "for it."
            }
            let problem = Self.cursorProblem(
                writer: writer, watchLost: watchLost, movieName: name, separate: separate)
            // The written file attached to the segment's media (spec §11 CU-34 (c)): the settle
            // probe ran before it existed. A failed attach leaves the segment as CU-18 left it.
            var attached: MediaCursor?
            if let url, case .success(let attachment) = MediaImporter.cursorAttachment(
                at: url, to: landed.descriptor)
            {
                attached = attachment.cursor
            }
            DispatchQueue.main.async {
                then(
                    landed.withCursor(
                        url: url, problem: problem,
                        image: url == nil ? nil : CursorImageMode.none, attached: attached))
            }
        }
    }

    /// A window's frame in global points from the window list, or nil.
    private static func windowBounds(_ id: CGWindowID) -> CGRect? {
        guard
            let list = CGWindowListCopyWindowInfo(.optionIncludingWindow, id)
                as? [[String: Any]],
            let bounds = list.first?[kCGWindowBounds as String] as? NSDictionary
        else { return nil }
        return CGRect(dictionaryRepresentation: bounds as CFDictionary)
    }

    /// A finite value above 0, else 1, so the header and the geometry always pass the core's
    /// check.
    private static func positive(_ value: Double) -> Double {
        value.isFinite && value > 0 ? value : 1
    }
}
import AppKit

/// The Picture sub-tab's Cursor section (road map creator-jobs CU3b, CU4, spec §11 CU-38 (b),
/// CU-40), after Background and before Shadow: Show cursor, Size, Style, Smoothing, Hide when
/// idle, Clicks, Ripple color, Ripple size and Polish. Each row writes only its own key through
/// `VideoPatch.cursorPart` as one named undo step. Inside an action Size and Ripple size animate;
/// Show, Style, Clicks and Ripple color switch at the end (CU-30); Smoothing, Hide when idle and
/// Polish are the clip's — `InspectorBinding.structural(video:for:)` sends them to the base (⊘),
/// and stores the defaults on a base with no cursor when an end key is written. Smoothing and
/// Hide when idle read the clip's BASE cursor, never the evaluated props.
extension VideoPane {

    /// The section's gate: every selected clip is a media or still clip whose media has a cursor
    /// file the movie's picture does not already show (`media.cursor` with `in_picture` false).
    /// `ClipPane.structureSignature` carries it, so a relink, an undo or a landing that changes
    /// the media's `cursor` under a fixed selection adds or removes the section.
    var allCursored: Bool {
        let clips = binding.clips
        let snapshot = binding.snapshot
        return !clips.isEmpty
            && clips.allSatisfy { clip in
                switch clip.source {
                case .media, .still:
                    guard let cursor = snapshot.media(for: clip)?.cursor else { return false }
                    return !cursor.inPicture
                default:
                    return false
                }
            }
    }

    func cursorSection() -> InspectorSection {
        let binding = self.binding
        /// The evaluated props (the action's end with one selected), the defaults without any.
        func props() -> CursorProps { binding.videoProps.cursor ?? CursorProps() }
        /// The first clip's BASE cursor — what the recipe reads `smoothing` and `hide_idle`
        /// from (CU-30) — and the defaults in `.defaults` mode, a row's reset.
        func base() -> CursorProps {
            guard binding.mode != .defaults else { return CursorProps() }
            return binding.videoClips.first?.video?.cursor ?? CursorProps()
        }
        func baseMixed<T: Equatable>(_ read: @escaping (CursorProps) -> T) -> Bool {
            binding.mixed(binding.videoClips) { read($0.video?.cursor ?? CursorProps()) }
        }
        func on() -> Bool { props().show }
        func ops(_ value: Bool) -> [ReelOp] {
            binding.ops(video: VideoPatch(cursorPart: CursorPatch(show: value)))
        }
        func part(_ patch: CursorPatch) -> [ReelOp] {
            binding.ops(video: VideoPatch(cursorPart: patch))
        }
        func ripples() -> Bool { props().clicks == .ripple }
        let styles = CursorStyle.allCases
        let clicks = CursorClicks.allCases
        let smoothing = CursorProps.smoothingSteps
        let hiding = CursorProps.hideIdleSteps
        let fallback = GraphicSchemaRows.rgba(css: CursorProps.defaultClickColor) ?? [1, 1, 1, 0.8]
        func rippleColor() -> RGBA {
            let css = ReelColor.normalise(props().clickColor) ?? CursorProps.defaultClickColor
            return GraphicSchemaRows.rgba(css: css) ?? fallback
        }
        let reset: CursorPatch = {
            let d = CursorProps()
            return CursorPatch(
                show: d.show, scale: d.scale, style: d.style, smoothing: d.smoothing,
                hideIdle: .some(d.hideIdle), clicks: d.clicks, clickColor: d.clickColor,
                clickSize: d.clickSize)
        }()
        let polish = OptionButtonControl(
            title: "Polish",
            action: { binding.apply("Polish Cursor", part(CursorProps.polished)) },
            enabled: { true }, onEdit: { binding.edited() })
        polish.toolTip = "Smoothing Medium and Hide when idle after 3 s"
        return InspectorSection(
            id: "video.cursor", title: "Cursor",
            summary: {
                let p = props()
                guard p.show || p.clicks == .ripple else { return "off" }
                return (p.style == .arrow ? "arrow" : "on")
                    + (p.clicks == .ripple ? " + ripples" : "")
            },
            reset: { binding.apply("Reset Cursor", part(reset)) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Show cursor", binding, name: "Show Cursor", read: on, ops: ops,
                    mixed: { binding.mixedVideo { $0.cursor?.show ?? true } }),
                inspectorValueRow(
                    "Size", binding, name: "Cursor Size", unit: "%", decimals: 0, min: 25,
                    max: 800, sliderMax: 400, quick: [50, 100, 150, 200, 400],
                    read: { props().scale * 100 },
                    ops: { part(CursorPatch(scale: $0 / 100)) },
                    mixed: { binding.mixedVideo { $0.cursor?.scale ?? 1 } }),
                inspectorPopupRow(
                    "Style", binding, name: "Cursor Style", items: ["As recorded", "Arrow"],
                    read: { styles.firstIndex(of: props().style) ?? 0 },
                    ops: { index in
                        guard styles.indices.contains(index) else { return [] }
                        return part(CursorPatch(style: styles[index]))
                    },
                    mixed: { binding.mixedVideo { $0.cursor?.style ?? .recorded } }),
                inspectorPopupRow(
                    "Smoothing", binding, name: "Cursor Smoothing", items: smoothing.map(\.title),
                    read: { smoothing.firstIndex { $0.value == base().smoothing } ?? -1 },
                    ops: { index in
                        guard smoothing.indices.contains(index) else { return [] }
                        return part(CursorPatch(smoothing: smoothing[index].value))
                    },
                    mixed: { baseMixed { $0.smoothing } }),
                inspectorPopupRow(
                    "Hide when idle", binding, name: "Hide Cursor When Idle",
                    items: hiding.map(\.title),
                    read: { hiding.firstIndex { $0.value == base().hideIdle } ?? -1 },
                    ops: { index in
                        guard hiding.indices.contains(index) else { return [] }
                        return part(CursorPatch(hideIdle: .some(hiding[index].value)))
                    },
                    mixed: { baseMixed { $0.hideIdle } }),
                inspectorPopupRow(
                    "Clicks", binding, name: "Cursor Clicks", items: ["None", "Ripple"],
                    read: { clicks.firstIndex(of: props().clicks) ?? 0 },
                    ops: { index in
                        guard clicks.indices.contains(index) else { return [] }
                        return part(CursorPatch(clicks: clicks[index]))
                    },
                    mixed: { binding.mixedVideo { $0.cursor?.clicks ?? .off } }),
                inspectorColorRow(
                    "Ripple color", binding, name: "Ripple Color", read: rippleColor,
                    ops: { part(CursorPatch(clickColor: GraphicSchemaRows.css($0))) },
                    mixed: {
                        binding.mixedVideo {
                            ReelColor.normalise($0.cursor?.clickColor ?? CursorProps.defaultClickColor)
                        }
                    },
                    enabled: ripples, discrete: true),
                inspectorValueRow(
                    "Ripple size", binding, name: "Ripple Size", unit: "%", decimals: 0,
                    min: 25, max: 400, quick: [50, 100, 150, 200],
                    read: { props().clickSize * 100 },
                    ops: { part(CursorPatch(clickSize: $0 / 100)) },
                    mixed: { binding.mixedVideo { $0.cursor?.clickSize ?? 1 } },
                    enabled: ripples),
                inspectorRow(
                    nil, [polish], binding: binding, writes: part(CursorProps.polished)),
            ])
    }
}
